/**
 * errors.js
 *
 * Centralised custom error classes for the Express application.
 * Every class extends the native Error so that:
 *   - instanceof checks work correctly throughout the stack.
 *   - stack traces are captured at the point of construction.
 *   - the error-handling middleware can branch purely on class type
 *     or on the attached `statusCode` / `code` properties.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError is the root class for every domain error in this application.
 * It should never be thrown directly; use one of the concrete subclasses.
 *
 * @property {number}  statusCode  - HTTP status code sent to the client.
 * @property {string}  code        - Machine-readable error identifier.
 * @property {boolean} isOperational
 *   true  → expected / handled error (validation failure, missing resource …)
 *   false → unexpected / programmer error (should be logged & investigated)
 */
class AppError extends Error {
  /**
   * @param {string} message     - Human-readable description.
   * @param {number} statusCode  - HTTP status code (default 500).
   * @param {string} code        - Machine-readable code (default 'INTERNAL_ERROR').
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR') {
    super(message);

    // Restore the correct prototype chain when targeting ES5 (TypeScript / Babel).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = true;

    // Capture a clean stack trace (omits the AppError constructor frame).
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   // → HTTP 404  { error: { code: 'USER_NOT_FOUND', message: 'User not found' } }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]  - Defaults to 'Resource not found'.
   * @param {string} [code]     - Defaults to 'NOT_FOUND'.
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when client-supplied data fails business-rule or schema validation.
 * Carries an optional `details` array so that multiple field errors can be
 * returned in a single response.
 *
 * @example
 *   throw new ValidationError('Invalid request body', [
 *     { field: 'email', message: 'Must be a valid e-mail address' },
 *     { field: 'age',   message: 'Must be a positive integer' },
 *   ]);
 *   // → HTTP 422  { error: { code: 'VALIDATION_ERROR', message: '…', details: […] } }
 */
class ValidationError extends AppError {
  /**
   * @param {string}   [message]  - Defaults to 'Validation failed'.
   * @param {Array}    [details]  - Per-field validation messages (default []).
   * @param {string}   [code]     - Defaults to 'VALIDATION_ERROR'.
   */
  constructor(message = 'Validation failed', details = [], code = 'VALIDATION_ERROR') {
    super(message, 422, code);
    // Attach the granular field-level errors so callers can surface them.
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails (connection lost, query timeout,
 * constraint violation that was not caught at the validation layer, etc.).
 * The original low-level error is stored as `cause` for server-side logging
 * but is never forwarded to the client.
 *
 * @example
 *   try {
 *     await db.query('SELECT …');
 *   } catch (dbErr) {
 *     throw new DatabaseError('Failed to fetch users', dbErr);
 *   }
 *   // → HTTP 503  { error: { code: 'DATABASE_ERROR', message: 'Failed to fetch users' } }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]       - Defaults to 'A database error occurred'.
   * @param {Error}  [cause]         - The original low-level error (not sent to client).
   * @param {string} [code]          - Defaults to 'DATABASE_ERROR'.
   */
  constructor(
    message = 'A database error occurred',
    cause   = null,
    code    = 'DATABASE_ERROR',
  ) {
    super(message, 503, code);
    // `cause` is intentionally kept off the serialised response to avoid
    // leaking internal implementation details (query text, table names …).
    this.cause = cause;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application entry-point.
 *
 * Error-handling strategy
 * ───────────────────────
 * Route handlers no longer call res.status(…).json(…) for error conditions.
 * Instead they throw (or, inside async handlers, return next(err) / let the
 * asyncHandler wrapper do it automatically).  A single centralised
 * errorHandler middleware at the bottom of the stack intercepts every error,
 * maps it to the correct HTTP status code, and writes a uniform JSON envelope.
 *
 * Uniform error envelope:
 *   {
 *     "error": {
 *       "code":    "MACHINE_READABLE_CODE",
 *       "message": "Human-readable description",
 *       "details": [ … ]   // only present for ValidationError
 *     }
 *   }
 */

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Utility: wrap an async route handler so that any rejected promise (or
// thrown error) is automatically forwarded to next(), removing the need for
// try/catch boilerplate in every handler.
// ---------------------------------------------------------------------------

/**
 * Wraps an async Express route handler and forwards any error to next().
 *
 * @param   {Function} fn  - async (req, res, next) => …
 * @returns {Function}     - Express-compatible (req, res, next) handler.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// In-memory data store (stand-in for a real database layer)
// ---------------------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe — never throws.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

