 * GET /users
 * Returns all users.
 * Demonstrates DatabaseError: if the data store is unavailable we throw
 * a DatabaseError and let the central handler deal with it.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Simulate a guard that would normally wrap a real DB call.
  if (!USERS) {
    throw new DatabaseError('Failed to retrieve users from the database');
  }

  res.json(USERS);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 * Demonstrates:
 *   - ValidationError when :id is not a positive integer.
 *   - NotFoundError   when no user matches the given id.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  // --- Validate ---------------------------------------------------------
  if (isNaN(id) || id <= 0) {
    throw new ValidationError('Invalid user id', [
      { field: 'id', message: 'Must be a positive integer' },
    ]);
  }

  // --- Simulate DB lookup -----------------------------------------------
  const user = USERS.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'USER_NOT_FOUND');
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 * Demonstrates ValidationError for missing / malformed fields.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body ?? {};
  const validationErrors = [];

  // --- Field-level validation -------------------------------------------
  if (!name || typeof name !== 'string' || name.trim() === '') {
    validationErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string') {
    validationErrors.push({ field: 'email', message: 'Email is required' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    validationErrors.push({ field: 'email', message: 'Must be a valid e-mail address' });
  }

  if (validationErrors.length > 0) {
    throw new ValidationError('Invalid user data', validationErrors);
  }

  // --- Simulate duplicate-email DB constraint ---------------------------
  const duplicate = USERS.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (duplicate) {
    throw new ValidationError('Email address is already in use', [
      { field: 'email', message: 'A user with this e-mail already exists' },
    ]);
  }

  // --- Persist (in-memory) ----------------------------------------------
  const newUser = { id: USERS.length + 1, name: name.trim(), email };
  USERS.push(newUser);

  res.status(201).json(newUser);
}));

// ---------------------------------------------------------------------------
// 404 catch-all — must be registered AFTER all valid routes
// ---------------------------------------------------------------------------

/**
 * Catches requests to routes that do not exist and converts them into a
 * NotFoundError so the central error handler can serialise them uniformly.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`, 'ROUTE_NOT_FOUND'));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Single source of truth for turning any error into an HTTP response.
 *
 * Decision tree:
 *   1. AppError (isOperational) → use err.statusCode + err.code.
 *   2. SyntaxError from express.json() body parser → treat as 400.
 *   3. Everything else → 500 INTERNAL_ERROR (details hidden from client).
 *
 * Only in non-production environments is the stack trace included in the
 * response to aid local debugging.
 *
 * Signature must have exactly four parameters so Express recognises this
 * as an error-handling middleware (even if `next` is unused here).
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // --- 1. Always log the full error on the server side ------------------
  console.error('[ErrorHandler]', {
    name:       err.name,
    message:    err.message,
    code:       err.code,
    statusCode: err.statusCode,
    // For DatabaseError, also log the underlying cause.
    ...(err.cause ? { cause: err.cause?.message ?? String(err.cause) } : {}),
    stack:      err.stack,
  });

  // --- 2. Determine status code -----------------------------------------
  let statusCode = 500;
  let code       = 'INTERNAL_ERROR';
  let message    = 'An unexpected error occurred';
  let details;

  if (err instanceof AppError) {
    // Known, operational error — surface its properties directly.
    statusCode = err.statusCode;
    code       = err.code;
    message    = err.message;

    // Include per-field details only for ValidationError.
    if (err instanceof ValidationError && Array.isArray(err.details) && err.details.length > 0) {
      details = err.details;
    }
