    // express.json() body-parser emits a SyntaxError for malformed JSON.
    statusCode = 400;
    code       = 'MALFORMED_JSON';
    message    = 'Request body contains invalid JSON';
  }
  // All other unexpected errors fall through with the 500 defaults above.

  // --- 3. Build the response envelope -----------------------------------
  const body = {
    error: {
      code,
      message,
      ...(details !== undefined ? { details } : {}),
      // Attach stack trace in development only — never in production.
      ...(process.env.NODE_ENV !== 'production' ? { stack: err.stack } : {}),
    },
  };

  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Start server (skipped when file is required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

