/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and carries:
 *   - statusCode  – the HTTP status code that should be returned to the client
 *   - isOperational – true means "known, expected error" (safe to surface);
 *                     false / undefined means "programmer error" (should not
 *                     leak internal detail to the client)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError is the root class for all intentional, operational errors thrown
 * inside route handlers or service functions.  It is never thrown directly;
 * use one of the concrete sub-classes below.
 */
class AppError extends Error {
  /**
   * @param {string}  message     – Human-readable description (logged server-side).
   * @param {number}  statusCode  – HTTP status code sent to the client.
   * @param {string}  [code]      – Machine-readable error code, e.g. "NOT_FOUND".
   * @param {object}  [details]   – Optional structured details (validation fields, etc.).
   */
  constructor(message, statusCode, code, details) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation if this file is ever compiled.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name; // e.g. "NotFoundError"
    this.statusCode  = statusCode;
    this.code        = code;
    this.details     = details || null;
    this.isOperational = true; // flag used by the error handler middleware

    // Captures a clean stack trace that omits this constructor frame.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', { userId: 42 });
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]  – Defaults to "Resource not found".
   * @param {object} [details]  – Optional structured context (e.g. which id was missing).
   */
  constructor(message = 'Resource not found', details) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when request input fails business-rule or schema validation.
 * Carries a `fields` map so the client can display per-field messages.
 *
 * @example
 *   throw new ValidationError('Invalid request body', {
 *     email: 'Must be a valid e-mail address',
 *     age:   'Must be a positive integer',
 *   });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message]  – Defaults to "Validation failed".
   * @param {object} [fields]   – Map of field name → error message.
   */
  constructor(message = 'Validation failed', fields) {
    // `fields` is passed through as `details` and also kept as its own
    // named property for convenience.
    super(message, 422, 'VALIDATION_ERROR', fields);
    this.fields = fields || null;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails (connection refused, query error,
 * constraint violation, etc.).  The original low-level error is stored in
 * `this.cause` for server-side logging but is **never** forwarded to the
 * client response.
 *
 * @example
 *   try {
 *     await db.query(sql, params);
 *   } catch (dbErr) {
 *     throw new DatabaseError('Could not fetch users', dbErr);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]     – Defaults to "A database error occurred".
   * @param {Error}  [cause]       – The underlying driver / ORM error.
   */
  constructor(message = 'A database error occurred', cause) {
    super(message, 503, 'DATABASE_ERROR');

    // Store the raw cause for server-side diagnostics only.
    // The error handler middleware must NOT expose `cause` to the client.
    this.cause = cause || null;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * Express application with centralised error-handling middleware.
 *
 * Error-handling strategy
 * ────────────────────────
 *  1. Route handlers throw an AppError sub-class (NotFoundError,
 *     ValidationError, DatabaseError) instead of calling res.status().json()
 *     inline.
 *  2. The async wrapper `asyncHandler` catches any synchronous or
 *     asynchronous throw and forwards it to next(), feeding Express's error
 *     pipeline.
 *  3. A dedicated 404 catch-all middleware converts "no route matched" into a
 *     NotFoundError before the error handler runs.
 *  4. The centralised errorHandler middleware at the bottom of the file
 *     formats every error into a consistent JSON envelope and logs it.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Utility: async wrapper
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so that any rejected promise (or synchronous
 * throw) is automatically forwarded to Express's next(err) pipeline instead
 * of leaving an unhandled-rejection warning.
 *
 * Usage:
 *   app.get('/path', asyncHandler(async (req, res) => { ... }));
 *
 * @param   {Function} fn  – Async (or sync) Express route handler.
 * @returns {Function}     – Express-compatible middleware.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – always succeeds.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// In-memory data store (replaces a real DB for this example)
// ---------------------------------------------------------------------------
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

/**
 * GET /users
 * Returns the full list of users.
 *
 * Simulated DB error: pass ?fail=1 to trigger a DatabaseError.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Simulate a database failure so DatabaseError can be exercised.
  if (req.query.fail === '1') {
    throw new DatabaseError(
      'Could not retrieve users from the database',
      new Error('Connection refused'), // raw driver error – never sent to client
    );
  }

  res.json(USERS);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Throws:
 *   ValidationError – if :id is not a positive integer.
 *   NotFoundError   – if no user exists with that id.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id < 1) {
    throw new ValidationError('Invalid user id', {
      id: 'Must be a positive integer',
    });
  }

  const user = USERS.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, { userId: id });
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 *
 * Body: { name: string, email: string }
 *
 * Throws:
 *   ValidationError – if required fields are missing or malformed.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body || {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'Name is required and must be a non-empty string';
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.email = 'A valid e-mail address is required';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Request body validation failed', fieldErrors);
  }

  const newUser = { id: USERS.length + 1, name: name.trim(), email: email.trim() };
  USERS.push(newUser);

  res.status(201).json(newUser);
}));

// ---------------------------------------------------------------------------
// 404 catch-all  (must come after all real routes)
// ---------------------------------------------------------------------------

/**
 * Any request that reaches this middleware did not match a route above.
 * Convert it to a NotFoundError so the single error handler below can
 * respond uniformly.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Express identifies this as an error-handling middleware because it declares
 * four parameters (err, req, res, next).  It must be registered LAST, after
 * all routes and other middleware.
 *
 * Behaviour
 * ──────────
 *  • Operational errors (AppError sub-classes) → structured JSON response at
 *    the error's own statusCode.
 *  • Unknown / programmer errors                → 500 with a generic message
 *    (internal detail is logged but never leaked to the client).
 *
 * Response envelope
 * ─────────────────
 *  {
 *    "error": {
 *      "code":    "NOT_FOUND",           // machine-readable
 *      "message": "User … not found",    // human-readable
 *      "details": { … } | null           // optional field-level info
 *    }
 *  }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Log the error server-side ────────────────────────────────────────
  //    For operational errors we keep the log concise; for unexpected errors
  //    we want the full stack trace.
  if (err.isOperational) {
    console.error(
      `[${new Date().toISOString()}] ${err.name} (${err.statusCode}): ${err.message}`,
      err.details ? `| details: ${JSON.stringify(err.details)}` : '',
      // Log the underlying cause for DatabaseErrors without exposing it to the client.
      err.cause   ? `| cause: ${err.cause.message}` : '',
    );
  } else {
    // Unexpected error – log the full stack so engineers can diagnose it.
    console.error(`[${new Date().toISOString()}] Unexpected error:`, err);
  }

  // ── 2. Build the client-facing response ─────────────────────────────────

  if (err.isOperational) {
    // Known, intentional error – surface safe detail.
    return res.status(err.statusCode).json({
      error: {
        code:    err.code,
        message: err.message,
        // `details` / `fields` are safe to forward (they were crafted by us).
        // DatabaseError deliberately sets details to null in its constructor,
        // so internal DB information is never included here.
        details: err.details ?? null,
      },
    });
  }

  // Unknown / programmer error – return a generic 500.
  return res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
      details: null,
    },
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

