/**
 * errors.js
 *
 * Centralised application error hierarchy.
 *
 * Every class extends the built-in Error so that:
 *   - instanceof checks work correctly across the whole app
 *   - stack traces are captured automatically
 *   - the Express error-handling middleware can branch on type
 *
 * Usage in a route handler:
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   // Instead of: res.status(404).json({ error: 'User not found' })
 *   throw new NotFoundError('User not found');
 *
 *   // Instead of: res.status(400).json({ error: 'Email is required' })
 *   throw new ValidationError('Email is required', ['email']);
 *
 *   // Instead of: res.status(500).json({ error: 'Query failed' })
 *   throw new DatabaseError('Query failed', originalDbError);
 */

'use strict';

// ─── Base Application Error ───────────────────────────────────────────────────

/**
 * AppError
 *
 * Abstract base class for all application-level errors.
 * Never thrown directly — always use a concrete sub-class.
 *
 * @property {number}  statusCode   - HTTP status code sent to the client.
 * @property {string}  code         - Machine-readable error identifier.
 * @property {boolean} isOperational - true  → expected, safe to expose to client.
 *                                     false → unexpected programmer error, hide details.
 */
class AppError extends Error {
  /**
   * @param {string} message     - Human-readable description of the problem.
   * @param {number} statusCode  - HTTP status code (e.g. 400, 404, 500).
   * @param {string} code        - Short constant identifying the error type.
   * @param {boolean} isOperational
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct prototype chain so that `instanceof` works when
    // the code is compiled/transpiled (e.g. TypeScript or Babel).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = new.target.name; // e.g. "NotFoundError"
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean V8 stack trace that starts at the call site,
    // omitting this constructor frame.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Serialise the error into a plain object suitable for a JSON response body.
   * Concrete sub-classes can override this to add extra fields.
   *
   * @returns {{ error: string, code: string, statusCode: number }}
   */
  toJSON() {
    return {
      error: this.message,
      code: this.code,
      statusCode: this.statusCode,
    };
  }
}

// ─── NotFoundError (HTTP 404) ─────────────────────────────────────────────────

/**
 * NotFoundError
 *
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found');
 *   throw new NotFoundError('Order not found', 'Order', orderId);
 */
class NotFoundError extends AppError {
  /**
   * @param {string}           message        - Human-readable message.
   * @param {string|null}      [resourceType] - Name of the missing resource (e.g. "User").
   * @param {string|number|null} [resourceId] - ID that was looked up, for context.
   */
  constructor(
    message = 'The requested resource was not found',
    resourceType = null,
    resourceId = null,
  ) {
    super(message, 404, 'NOT_FOUND');

    this.resourceType = resourceType;
    this.resourceId = resourceId;
  }

  toJSON() {
    const base = super.toJSON();

    // Only include resource metadata when it was supplied — avoids leaking
    // internal field names for generic 404s.
    if (this.resourceType !== null) {
      base.resourceType = this.resourceType;
    }
    if (this.resourceId !== null) {
      base.resourceId = this.resourceId;
    }

    return base;
  }
}

// ─── ValidationError (HTTP 400) ──────────────────────────────────────────────

/**
 * ValidationError
 *
 * Thrown when the client submits a request that fails input validation.
 *
 * @example
 *   throw new ValidationError('Email is required');
 *   throw new ValidationError('Invalid request body', ['email', 'password']);
 *   throw new ValidationError('Validation failed', [
 *     { field: 'email',    message: 'Must be a valid email address' },
 *     { field: 'password', message: 'Must be at least 8 characters'  },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}                          message - Human-readable summary.
   * @param {Array<string|{field,message}>}  [fields] - Affected fields or detailed
   *                                                    per-field error objects.
   */
  constructor(message = 'Validation failed', fields = []) {
    super(message, 400, 'VALIDATION_ERROR');

    // Normalise plain strings into { field, message } objects so callers
    // always receive a consistent shape regardless of how the error was built.
    this.fields = fields.map((f) =>
      typeof f === 'string' ? { field: f, message: `${f} is invalid` } : f,
    );
  }

  toJSON() {
    const base = super.toJSON();

    if (this.fields.length > 0) {
      base.fields = this.fields;
    }

    return base;
  }
}

// ─── DatabaseError (HTTP 500) ─────────────────────────────────────────────────

/**
 * DatabaseError
 *
 * Thrown when a database operation fails unexpectedly.
 * Marked as non-operational (isOperational = false) because the root cause
 * is a server-side problem, not a client mistake — the error middleware will
 * suppress internal details in production responses.
 *
 * @example
 *   try {
 *     await db.query(sql, params);
 *   } catch (err) {
 *     throw new DatabaseError('Failed to fetch users', err);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string}    message        - High-level description shown to the client.
   * @param {Error|null} [originalError] - The underlying DB driver error; kept for
   *                                      server-side logging, never sent to clients.
   */
  constructor(
    message = 'A database error occurred',
    originalError = null,
  ) {
    // isOperational = false: unexpected failure, hide internals from clients.
    super(message, 500, 'DATABASE_ERROR', false);

    // Preserve the root cause for server-side diagnostics (logs, APM) without
    // ever serialising it into the HTTP response.
    this.originalError = originalError;
  }

  // toJSON() intentionally inherits from AppError without exposing originalError.
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 *
 * Express application entry point.
 *
 * Error-handling strategy
 * ───────────────────────
 * Route handlers never call res.status().json() for errors.  Instead they
 * `throw` (sync) or call `next(err)` (async) with one of the typed error
 * classes from errors.js.  A single centralised middleware at the bottom of
 * the file translates every thrown error into a consistent JSON response.
 *
 * Middleware registration order (matters for Express):
 *   1. Body parsers / request prep
 *   2. Application routes
 *   3. 404 catch-all  ← must come after all routes
 *   4. Error handler  ← must be last, must have 4 parameters (err,req,res,next)
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ─── Request parsing ──────────────────────────────────────────────────────────

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// ─── In-memory data store (placeholder until a real DB is wired up) ───────────

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Lightweight liveness probe — no auth, no DB, always fast.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns the full list of users.
 *
 * Error cases:
 *   - If the data source raises an unexpected error a DatabaseError is thrown
 *     so the error middleware can handle it uniformly.
 */
app.get('/users', (req, res) => {
  // Simulate what real DB access would look like: wrap in try/catch and
  // convert driver-level errors into a typed DatabaseError.
  try {
    const users = getUsers();
    res.json(users);
  } catch (err) {
    // Re-wrap unexpected errors (e.g. DB driver failures) into a typed error
    // so the centralised handler always receives a known shape.
    throw new DatabaseError('Failed to retrieve users', err);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric ID.
 *
 * Error cases:
 *   - Non-numeric :id          → ValidationError (400)
 *   - ID not found in the store → NotFoundError   (404)
 *   - Unexpected data error     → DatabaseError   (500)
 */
app.get('/users/:id', (req, res) => {
  const rawId = req.params.id;

  // Validate that the segment is actually a number before touching the store.
  if (!/^\d+$/.test(rawId)) {
    throw new ValidationError('User ID must be a positive integer', ['id']);
  }

  const id = parseInt(rawId, 10);

  try {
    const user = getUserById(id);

    if (!user) {
      throw new NotFoundError(`User with ID ${id} not found`, 'User', id);
    }

    res.json(user);
  } catch (err) {
    // Re-throw our own typed errors untouched; only wrap truly unexpected ones.
    if (err instanceof AppError) throw err;
    throw new DatabaseError('Failed to retrieve user', err);
  }
});

/**
 * POST /users
 *
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Error cases:
 *   - Missing / blank name or email → ValidationError (400)
 *   - Duplicate email               → ValidationError (400)
 *   - Unexpected persistence error  → DatabaseError   (500)
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};

  // Collect all field-level problems before throwing so the client gets
  // a complete picture in a single round-trip.
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || email.trim() === '') {
    fieldErrors.push({ field: 'email', message: 'Email is required and must be a non-empty string' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
    fieldErrors.push({ field: 'email', message: 'Email must be a valid email address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid user data', fieldErrors);
  }

  try {
    const existing = USERS.find(
      (u) => u.email.toLowerCase() === email.trim().toLowerCase(),
    );

    if (existing) {
      throw new ValidationError('A user with this email already exists', [
        { field: 'email', message: 'Email is already registered' },
      ]);
    }

    const newUser = {
      id:    USERS.length + 1,
      name:  name.trim(),
      email: email.trim().toLowerCase(),
    };

    USERS.push(newUser);

    res.status(201).json(newUser);
  } catch (err) {
    if (err instanceof AppError) throw err;
    throw new DatabaseError('Failed to create user', err);
  }
});

/**
 * DELETE /users/:id
 *
 * Removes a user by numeric ID.
 *
 * Error cases:
 *   - Non-numeric :id  → ValidationError (400)
 *   - ID not found     → NotFoundError   (404)
 *   - Unexpected error → DatabaseError   (500)
 */
app.delete('/users/:id', (req, res) => {
  const rawId = req.params.id;

  if (!/^\d+$/.test(rawId)) {
    throw new ValidationError('User ID must be a positive integer', ['id']);
  }

  const id = parseInt(rawId, 10);

  try {
    const index = USERS.findIndex((u) => u.id === id);

    if (index === -1) {
      throw new NotFoundError(`User with ID ${id} not found`, 'User', id);
    }

    const [deleted] = USERS.splice(index, 1);

    res.json({ message: 'User deleted successfully', user: deleted });
  } catch (err) {
    if (err instanceof AppError) throw err;
    throw new DatabaseError('Failed to delete user', err);
  }
});

// ─── 404 catch-all ────────────────────────────────────────────────────────────
//
// Must be registered AFTER all application routes.
// Converts any unmatched request into a NotFoundError so the error handler
// below formats it the same way as every other error.

app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ─── Centralised error-handling middleware ────────────────────────────────────
//
// Express identifies this as an error handler because it declares exactly
// four parameters (err, req, res, next).  It MUST be the last app.use() call.
//
// Responsibilities:
//   1. Log the error (always — even for 4xx, logs aid debugging).
//   2. Determine the correct HTTP status code.
//   3. Build a sanitised response body:
//        operational errors  → expose message + structured fields
//        non-operational     → hide internals, return generic message in prod
//   4. Never let the process crash from an unhandled route error.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Log ──────────────────────────────────────────────────────────────────
  // Always log the full error server-side; the client only sees a safe subset.
  const isProduction = process.env.NODE_ENV === 'production';

  if (err instanceof AppError) {
    // Operational errors (4xx) are INFO-level; server errors (5xx) are ERROR.
    const logLevel = err.statusCode < 500 ? 'warn' : 'error';
    console[logLevel](
      `[${err.code}] ${err.message}`,
      err.statusCode < 500 ? '' : err.stack,
    );
  } else {
    // Completely unexpected error — log everything including the stack.
    console.error('[UNHANDLED_ERROR]', err);
  }

  // ── 2. Determine status code ─────────────────────────────────────────────────
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // ── 3. Build response body ───────────────────────────────────────────────────
  let body;

  if (err instanceof AppError && err.isOperational) {
    // Safe to expose: the error was deliberately thrown by application code.
    body = err.toJSON();
  } else {
    // Non-operational or completely unknown error: hide internals in production.
    body = {
      error:      isProduction ? 'An unexpected error occurred' : err.message,
      code:       'INTERNAL_SERVER_ERROR',
      statusCode: 500,
      // Only include the stack in non-production for faster local debugging.
      ...(isProduction ? {} : { stack: err.stack }),
    };
  }

  // ── 4. Send ───────────────────────────────────────────────────────────────────
  res.status(statusCode).json(body);
});

// ─── Server bootstrap ─────────────────────────────────────────────────────────

const PORT = process.env.PORT ?? 3000;

// Only start listening when this file is run directly, not when it is
// require()'d by tests — avoids EADDRINUSE in test suites.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

