const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── instanceof chain ──────────────────────────────────────────────────────────
const nfe = new NotFoundError('User not found', 'User', 42);
const ve  = new ValidationError('Bad input', ['email', { field: 'name', message: 'required' }]);
const dbe = new DatabaseError('Query failed', new Error('connection refused'));

console.assert(nfe instanceof Error,        'NotFoundError extends Error');
console.assert(nfe instanceof AppError,     'NotFoundError extends AppError');
console.assert(nfe instanceof NotFoundError,'NotFoundError instanceof itself');
console.assert(!(nfe instanceof ValidationError), 'NotFoundError not a ValidationError');

console.assert(ve  instanceof Error,         'ValidationError extends Error');
console.assert(ve  instanceof AppError,      'ValidationError extends AppError');
console.assert(ve  instanceof ValidationError,'ValidationError instanceof itself');

console.assert(dbe instanceof Error,         'DatabaseError extends Error');
console.assert(dbe instanceof AppError,      'DatabaseError extends AppError');
console.assert(dbe instanceof DatabaseError, 'DatabaseError instanceof itself');

// ── statusCodes ───────────────────────────────────────────────────────────────
console.assert(nfe.statusCode === 404, 'NotFoundError statusCode 404');
console.assert(ve.statusCode  === 400, 'ValidationError statusCode 400');
console.assert(dbe.statusCode === 500, 'DatabaseError statusCode 500');

// ── error codes ───────────────────────────────────────────────────────────────
console.assert(nfe.code === 'NOT_FOUND',        'NotFoundError code');
console.assert(ve.code  === 'VALIDATION_ERROR', 'ValidationError code');
console.assert(dbe.code === 'DATABASE_ERROR',   'DatabaseError code');

// ── isOperational ─────────────────────────────────────────────────────────────
console.assert(nfe.isOperational === true,  'NotFoundError is operational');
console.assert(ve.isOperational  === true,  'ValidationError is operational');
console.assert(dbe.isOperational === false, 'DatabaseError is NOT operational');

// ── .name ─────────────────────────────────────────────────────────────────────
console.assert(nfe.name === 'NotFoundError',   'NotFoundError.name');
console.assert(ve.name  === 'ValidationError', 'ValidationError.name');
console.assert(dbe.name === 'DatabaseError',   'DatabaseError.name');

// ── toJSON shape ──────────────────────────────────────────────────────────────
const nfeJSON = nfe.toJSON();
console.assert(nfeJSON.error        === 'User not found', 'NFE message');
console.assert(nfeJSON.statusCode   === 404,              'NFE statusCode in JSON');
console.assert(nfeJSON.resourceType === 'User',           'NFE resourceType');
console.assert(nfeJSON.resourceId   === 42,               'NFE resourceId');

const veJSON = ve.toJSON();
console.assert(veJSON.error              === 'Bad input',          'VE message');
console.assert(veJSON.fields.length      === 2,                    'VE fields length');
console.assert(veJSON.fields[0].field    === 'email',              'VE field[0].field');
console.assert(veJSON.fields[0].message  === 'email is invalid',   'VE field[0].message (normalised)');
console.assert(veJSON.fields[1].field    === 'name',               'VE field[1].field (object)');
console.assert(veJSON.fields[1].message  === 'required',           'VE field[1].message (object)');

const dbeJSON = dbe.toJSON();
console.assert(dbeJSON.error      === 'Query failed',    'DBE message');
console.assert(!('originalError' in dbeJSON),            'originalError NOT in toJSON');

// ── stack captured ────────────────────────────────────────────────────────────
console.assert(typeof nfe.stack === 'string' && nfe.stack.length > 0, 'stack captured');

// ── DatabaseError preserves originalError for logging ─────────────────────────
console.assert(dbe.originalError instanceof Error,  'originalError preserved on instance');
console.assert(dbe.originalError.message === 'connection refused', 'originalError message');

// ── defaults ─────────────────────────────────────────────────────────────────
const bareNFE = new NotFoundError();
console.assert(bareNFE.message === 'The requested resource was not found', 'NFE default message');
console.assert(bareNFE.resourceType === null, 'NFE default resourceType null');

const bareVE = new ValidationError();
console.assert(bareVE.message === 'Validation failed',  'VE default message');
console.assert(bareVE.fields.length === 0,              'VE default fields empty');

const bareDBE = new DatabaseError();
console.assert(bareDBE.message       === 'A database error occurred', 'DBE default message');
console.assert(bareDBE.originalError === null,                        'DBE default originalError null');

console.log('All errors.js assertions passed ✓');
"

