// ── Minimal Express mock ──────────────────────────────────────────────────────
// We only need enough surface area to trace through our handlers.
const handlers = { GET: {}, POST: {}, DELETE: {} };
let notFoundMiddleware = null;
let errorMiddleware    = null;

const mockApp = {
  use(pathOrFn, fn) {
    const handler = fn ?? pathOrFn;
    if (handler.length === 4) { errorMiddleware    = handler; return; }
    if (handler.length === 3) { notFoundMiddleware = handler; return; }
  },
  get(path, fn)    { handlers.GET[path]    = fn; },
  post(path, fn)   { handlers.POST[path]   = fn; },
  delete(path, fn) { handlers.DELETE[path] = fn; },
  listen(port, cb) { cb && cb(); },
};

// Patch require so that 'express' returns a factory for our mock
const Module = require('module');
const _orig  = Module._resolveFilename;
const _load  = Module._load;
Module._load = function(req, parent, isMain) {
  if (req === 'express') {
    const factory = () => mockApp;
    factory.json       = () => (r, s, n) => n();
    factory.urlencoded = () => (r, s, n) => n();
    return factory;
  }
  return _load.apply(this, arguments);
};

// Load app (will register routes against our mock)
require('./app');

// ── Test helpers ───────────────────────────────────────────────────────────────
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

function makeRes() {
  const res = { _status: 200, _body: null };
  res.status = (s) => { res._status = s; return res; };
  res.json   = (b) => { res._body   = b; return res; };
  return res;
}

function callHandler(method, path, params = {}, body = {}) {
  return new Promise((resolve, reject) => {
    const handler = handlers[method][path];
    if (!handler) return reject(new Error('Route not registered: ' + method + ' ' + path));
    const req = { params, body };
    const res = makeRes();
    // Wrap in try to catch synchronous throws, pass to error middleware
    try {
      const result = handler(req, res, (err) => {
        if (err) reject(err); else resolve(res);
      });
      if (result && typeof result.then === 'function') {
        result.then(() => resolve(res)).catch(reject);
      } else {
        resolve(res);
      }
    } catch(err) {
      reject(err);
    }
  });
}

function runErrorMiddleware(err) {
  const res = makeRes();
  const req = { method: 'GET', path: '/test' };
  return new Promise((resolve) => {
    errorMiddleware(err, req, res, () => {});
    resolve(res);
  });
}

// ── Tests ──────────────────────────────────────────────────────────────────────
(async () => {
  // 1. GET /health always succeeds
  {
    const res = await callHandler('GET', '/health');
    console.assert(res._status === 200,            'health: 200');
