  // 12. DELETE /users/:id — success
  {
    // Alice is still in the store (id = 1)
    const res = await callHandler('DELETE', '/users/:id', { id: '1' });
    console.assert(res._status === 200,                     'delete: 200');
    console.assert(res._body.message === 'User deleted successfully', 'delete: message');
    console.assert(res._body.user.id === 1,                 'delete: correct user');
