    console.assert(res._body.resourceId     === 7,             'EH: resourceId');
    console.log('PASS  Error handler (NotFoundError → 404)');
  }

  // 14. Operational ValidationError → 400 + fields array
  {
    const err = new ValidationError('Bad data', [{ field: 'x', message: 'required' }]);
    const res = await runErrorMiddleware(err);
    console.assert(res._status            === 400,              'EH: 400 status');
    console.assert(res._body.code         === 'VALIDATION_ERROR','EH: VALIDATION_ERROR code');
    console.assert(Array.isArray(res._body.fields),             'EH: fields array');
    console.log('PASS  Error handler (ValidationError → 400)');
  }

  // 15. Non-operational DatabaseError → 500 + generic body (no originalError)
  {
    const orig = new Error('pg: connection refused');
    const err  = new DatabaseError('DB failure', orig);
    const res  = await runErrorMiddleware(err);
    console.assert(res._status  === 500,             'EH: 500 status');
    console.assert(res._body.code === 'INTERNAL_SERVER_ERROR', 'EH: INTERNAL_SERVER_ERROR code');
    console.assert(!res._body.originalError,         'EH: originalError NOT in response');
    console.log('PASS  Error handler (DatabaseError → 500, no internals)');
  }

  // 16. Plain Error (programmer mistake) → 500 + generic body
  {
    const err = new TypeError('Cannot read property of undefined');
    const res = await runErrorMiddleware(err);
    console.assert(res._status === 500,              'EH: unknown error 500');
    console.assert(res._body.code === 'INTERNAL_SERVER_ERROR', 'EH: generic code');
    console.log('PASS  Error handler (plain Error → 500)');
  }

  // 17. 404 catch-all middleware is registered
  {
    console.assert(typeof notFoundMiddleware === 'function', '404 catch-all registered');
    const req = { method: 'GET', path: '/no-such-route' };
    let passedErr = null;
    notFoundMiddleware(req, makeRes(), (err) => { passedErr = err; });
    console.assert(passedErr instanceof NotFoundError, '404 middleware passes NotFoundError');
    console.assert(passedErr.statusCode === 404,       '404 middleware: statusCode 404');
    console.log('PASS  404 catch-all middleware');
  }

  // 18. Error middleware is a 4-argument function (Express contract)
  {
    console.assert(errorMiddleware.length === 4, 'error handler has 4 params');
    console.log('PASS  Error handler arity (4 params)');
  }

  console.log('\nAll app.js assertions passed ✓');
})().catch((err) => { console.error('FAIL', err); process.exit(1); });
