  },
  get(path, fn)    { handlers.GET[path]    = fn; },
  post(path, fn)   { handlers.POST[path]   = fn; },
  delete(path, fn) { handlers.DELETE[path] = fn; },
  listen(port, cb) { cb && cb(); },
};

