/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and carries:
 *   - statusCode  – the HTTP status that should be sent to the client
 *   - isOperational – true  → expected, safe-to-expose error
 *                     false → unexpected programmer error (default for Error)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message        Human-readable description.
   * @param {number}  statusCode     HTTP status code (e.g. 404, 422, 500).
   * @param {string}  [errorCode]    Optional machine-readable code for clients.
   * @param {object}  [details]      Optional structured details (e.g. field errors).
   */
  constructor(message, statusCode, errorCode = null, details = null) {
    super(message);

    // Keep the prototype chain intact so `instanceof` checks work correctly
    // even after transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.errorCode   = errorCode;
    this.details     = details;
    this.isOperational = true; // all subclasses are considered operational

    // Capture a clean stack trace that excludes this constructor frame.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource]  Name of the missing resource (e.g. 'User').
   * @param {string} [id]        Identifier that was looked up.
   *
   * Examples
   *   throw new NotFoundError()
   *   throw new NotFoundError('User')
   *   throw new NotFoundError('User', '42')
   */
  constructor(resource = 'Resource', id = null) {
    const message = id
      ? `${resource} with id '${id}' was not found.`
      : `${resource} was not found.`;

    super(message, 404, 'NOT_FOUND');

    this.resource = resource;
    this.resourceId = id;
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}          [message]  Override the default message.
   * @param {object|Array}    [details]  Field-level validation failures.
   *
   * The `details` payload is intentionally flexible so it can wrap output
   * from libraries such as Joi, Zod, or express-validator without conversion.
   *
   * Examples
   *   throw new ValidationError('Email is required.')
   *   throw new ValidationError('Invalid input.', [
   *     { field: 'email', message: 'Must be a valid e-mail address.' },
   *     { field: 'age',   message: 'Must be a positive integer.'    },
   *   ])
   */
  constructor(message = 'Validation failed.', details = null) {
    super(message, 422, 'VALIDATION_ERROR', details);
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]         Human-readable description.
   * @param {Error}  [originalError]   The underlying driver/ORM error.
   *
   * The original error is stored on `this.cause` (aligned with the TC39
   * Error Cause proposal and Node ≥ 16.9).  It is intentionally NOT
   * forwarded to the client to avoid leaking internal details.
   *
   * Examples
   *   throw new DatabaseError()
   *   throw new DatabaseError('Could not save user.', pgError)
   */
  constructor(message = 'A database error occurred.', originalError = null) {
    super(message, 503, 'DATABASE_ERROR');

    // Store the root cause for server-side logging without exposing it.
    if (originalError) {
      this.cause = originalError;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Mock data store – stands in for a real DB layer
// ---------------------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health ----------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users -----------------------------------------------------------------
app.get('/users', (req, res) => {
  // Simulate a DB call – throw DatabaseError if the store is unavailable.
  if (!USERS) {
    throw new DatabaseError('Could not retrieve users from the database.');
  }

  res.json(USERS);
});

// GET /users/:id -------------------------------------------------------------
app.get('/users/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    throw new ValidationError('Invalid user id.', [
      { field: 'id', message: 'Must be a positive integer.' },
    ]);
  }

  const user = USERS.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError('User', req.params.id);
  }

  res.json(user);
});

// POST /users ----------------------------------------------------------------
app.post('/users', (req, res) => {
  const { name, email } = req.body;

  // Collect all field errors before throwing so the client gets them at once.
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'A valid e-mail address is required.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid user data.', fieldErrors);
  }

  // Check for duplicate e-mail.
  if (USERS.some((u) => u.email.toLowerCase() === email.toLowerCase())) {
    throw new ValidationError('A user with this e-mail address already exists.', [
      { field: 'email', message: 'E-mail must be unique.' },
    ]);
  }

  const newUser = { id: USERS.length + 1, name: name.trim(), email };
  USERS.push(newUser);

  res.status(201).json(newUser);
});

// PUT /users/:id -------------------------------------------------------------
app.put('/users/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    throw new ValidationError('Invalid user id.', [
      { field: 'id', message: 'Must be a positive integer.' },
    ]);
  }

  const index = USERS.findIndex((u) => u.id === id);

  if (index === -1) {
    throw new NotFoundError('User', req.params.id);
  }

  const { name, email } = req.body;
  const fieldErrors = [];

  if (name !== undefined) {
    if (typeof name !== 'string' || name.trim() === '') {
      fieldErrors.push({ field: 'name', message: 'Name must be a non-empty string.' });
    }
  }

  if (email !== undefined) {
    if (typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      fieldErrors.push({ field: 'email', message: 'Must be a valid e-mail address.' });
    } else if (
      USERS.some((u) => u.email.toLowerCase() === email.toLowerCase() && u.id !== id)
    ) {
      fieldErrors.push({ field: 'email', message: 'E-mail must be unique.' });
    }
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid update data.', fieldErrors);
  }

  USERS[index] = {
    ...USERS[index],
    ...(name  !== undefined && { name: name.trim() }),
    ...(email !== undefined && { email }),
  };

  res.json(USERS[index]);
});

// DELETE /users/:id ----------------------------------------------------------
app.delete('/users/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    throw new ValidationError('Invalid user id.', [
      { field: 'id', message: 'Must be a positive integer.' },
    ]);
  }

  const index = USERS.findIndex((u) => u.id === id);

  if (index === -1) {
    throw new NotFoundError('User', req.params.id);
  }

  USERS.splice(index, 1);
  res.status(204).send();
});

// ---------------------------------------------------------------------------
// 404 catch-all – must be placed AFTER all valid routes
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError(`Route '${req.method} ${req.path}'`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
//
// Express identifies this as an error handler because it declares FOUR
// parameters (err, req, res, next).  It must be the LAST app.use() call.
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Log the error on the server ──────────────────────────────────────
  //
  // Always log the full stack in development; in production you would pipe
  // this to a structured logger (e.g. Winston, Pino, Datadog).
  const isDev = process.env.NODE_ENV !== 'production';

  if (isDev) {
    console.error('[Error]', err);
  } else {
    // In production log enough to diagnose without leaking internals.
    console.error(`[Error] ${err.name}: ${err.message}`, {
      statusCode : err.statusCode,
      errorCode  : err.errorCode,
      path       : req.path,
      method     : req.method,
      // Include the cause if this is a DatabaseError
      ...(err.cause && { cause: err.cause.message }),
    });
  }

  // ── 2. Determine whether this is an operational (known) error ────────────
  //
  // Operational errors are expected, safe-to-describe conditions.
  // Non-operational errors (bugs / unexpected crashes) get a generic 500.
  const isOperational = err instanceof AppError && err.isOperational;

  // ── 3. Build the response payload ────────────────────────────────────────

  const statusCode = isOperational ? err.statusCode : 500;

  const payload = {
    error: {
      // Always present
      status  : statusCode,
      code    : isOperational ? err.errorCode   : 'INTERNAL_SERVER_ERROR',
      message : isOperational ? err.message     : 'An unexpected error occurred. Please try again later.',

      // Only include structured field details when present (e.g. ValidationError)
      ...(isOperational && err.details && { details: err.details }),

      // Only include a stack trace in development
      ...(isDev && { stack: err.stack }),
    },
  };

  res.status(statusCode).json(payload);
});

// ---------------------------------------------------------------------------
// Server bootstrap (skipped when required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

