  const index = USERS.findIndex((u) => u.id === id);

  if (index === -1) {
    throw new NotFoundError('User', req.params.id);
  }

  USERS.splice(index, 1);
  res.status(204).send();
});

// ---------------------------------------------------------------------------
// 404 catch-all – must be placed AFTER all valid routes
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError(`Route '${req.method} ${req.path}'`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
//
// Express identifies this as an error handler because it declares FOUR
// parameters (err, req, res, next).  It must be the LAST app.use() call.
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Log the error on the server ──────────────────────────────────────
  //
  // Always log the full stack in development; in production you would pipe
  // this to a structured logger (e.g. Winston, Pino, Datadog).
  const isDev = process.env.NODE_ENV !== 'production';

  if (isDev) {
    console.error('[Error]', err);
  } else {
    // In production log enough to diagnose without leaking internals.
    console.error(`[Error] ${err.name}: ${err.message}`, {
      statusCode : err.statusCode,
      errorCode  : err.errorCode,
      path       : req.path,
      method     : req.method,
      // Include the cause if this is a DatabaseError
      ...(err.cause && { cause: err.cause.message }),
    });
  }

  // ── 2. Determine whether this is an operational (known) error ────────────
  //
  // Operational errors are expected, safe-to-describe conditions.
  // Non-operational errors (bugs / unexpected crashes) get a generic 500.
  const isOperational = err instanceof AppError && err.isOperational;

  // ── 3. Build the response payload ────────────────────────────────────────

  const statusCode = isOperational ? err.statusCode : 500;

  const payload = {
    error: {
      // Always present
      status  : statusCode,
      code    : isOperational ? err.errorCode   : 'INTERNAL_SERVER_ERROR',
      message : isOperational ? err.message     : 'An unexpected error occurred. Please try again later.',

      // Only include structured field details when present (e.g. ValidationError)
      ...(isOperational && err.details && { details: err.details }),

      // Only include a stack trace in development
      ...(isDev && { stack: err.stack }),
    },
  };

  res.status(statusCode).json(payload);
});

// ---------------------------------------------------------------------------
// Server bootstrap (skipped when required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

