'use strict';
// ── Minimal supertest-style integration without an extra dependency ──────────
const http   = require('http');
const app    = require('./app');

const server = http.createServer(app);
server.listen(0); // OS-assigned port

const { port } = server.address();

function get(path) {
  return new Promise((resolve, reject) => {
    http.get({ hostname: '127.0.0.1', port, path }, res => {
      let body = '';
      res.on('data', d => body += d);
      res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(body) }));
    }).on('error', reject);
  });
}

function post(path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const req  = http.request(
      { hostname: '127.0.0.1', port, path, method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      res => {
        let body = '';
        res.on('data', d => body += d);
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(body) }));
      }
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function run() {
  // 1. GET /health → 200
  let r = await get('/health');
  console.assert(r.status === 200,           'GET /health → 200');
  console.assert(r.body.status === 'ok',     'GET /health body');

  // 2. GET /users → 200, array of 2
  r = await get('/users');
  console.assert(r.status === 200,           'GET /users → 200');
  console.assert(r.body.length === 2,        'GET /users → 2 users');

  // 3. GET /users/1 → 200, Alice
  r = await get('/users/1');
  console.assert(r.status === 200,           'GET /users/1 → 200');
  console.assert(r.body.name === 'Alice',    'GET /users/1 → Alice');

  // 4. GET /users/99 → 404, NOT_FOUND
  r = await get('/users/99');
  console.assert(r.status === 404,                        'GET /users/99 → 404');
  console.assert(r.body.error.code === 'NOT_FOUND',       'GET /users/99 → NOT_FOUND');
  console.assert(r.body.error.message === 'User not found.', 'GET /users/99 message');

  // 5. GET /users/abc → 422, VALIDATION_ERROR
  r = await get('/users/abc');
  console.assert(r.status === 422,                            'GET /users/abc → 422');
  console.assert(r.body.error.code === 'VALIDATION_ERROR',   'GET /users/abc → VALIDATION_ERROR');
  console.assert(r.body.error.fields.id !== undefined,       'GET /users/abc → fields.id present');

  // 6. POST /users valid → 201
  r = await post('/users', { name: 'Carol', email: 'carol@example.com' });
  console.assert(r.status === 201,           'POST /users valid → 201');
  console.assert(r.body.name === 'Carol',    'POST /users valid → Carol');

  // 7. POST /users missing fields → 422 with field errors
  r = await post('/users', {});
  console.assert(r.status === 422,                             'POST /users empty → 422');
  console.assert(r.body.error.code === 'VALIDATION_ERROR',    'POST /users empty → VALIDATION_ERROR');
  console.assert(r.body.error.fields.name  !== undefined,     'POST /users empty → fields.name');
  console.assert(r.body.error.fields.email !== undefined,     'POST /users empty → fields.email');

  // 8. POST /users bad email → 422 with fields.email only
  r = await post('/users', { name: 'Dave', email: 'not-an-email' });
  console.assert(r.status === 422,                             'POST /users bad email → 422');
  console.assert(r.body.error.fields.email !== undefined,     'POST /users bad email → fields.email');
  console.assert(r.body.error.fields.name  === undefined,     'POST /users bad email → no fields.name');

  // 9. GET /no-such-route → 404 catch-all
  r = await get('/no-such-route');
  console.assert(r.status === 404,                        'GET /unknown → 404');
  console.assert(r.body.error.code === 'NOT_FOUND',       'GET /unknown → NOT_FOUND code');

  console.log('All integration assertions passed.');
  server.close();
}

run().catch(err => { console.error(err); server.close(); process.exit(1); });
