assert(s4 === 503,                                   'status 503');
assert(b4.error.code    === 'DATABASE_ERROR',        'code DATABASE_ERROR');
assert(b4.error.message !== 'pg timeout',            'raw DB message suppressed');
assert(b4.error.message === 'An unexpected error occurred. Please try again later.',
  'generic message returned to client');

console.log('\n=== Error handler: plain Error (unexpected) ===');
const plain = new Error('Something blew up');
const { statusCode: s5, responseBody: b5 } = errorHandler(plain);
assert(s5 === 500,                               'status 500');
assert(b5.error.code    === 'INTERNAL_ERROR',    'code INTERNAL_ERROR');
assert(b5.error.message === 'An unexpected error occurred. Please try again later.',
  'generic message for unknown errors');

console.log('\n=== Error handler: custom AppError (operational) ===');
const custom = new AppError('Custom message', 409, 'CONFLICT', true);
const { statusCode: s6, responseBody: b6 } = errorHandler(custom);
assert(s6 === 409,                       'status 409');
assert(b6.error.code    === 'CONFLICT',  'code CONFLICT');
assert(b6.error.message === 'Custom message', 'message forwarded');

console.log('\n─────────────────────────────────────────────────');
console.log(\`Results: \${passed} passed, \${failed} failed\`);
if (failed > 0) process.exit(1);
