// ── Test 3: route logic unit tests ─────────────────────────────────────────
// We replicate each route's business logic in isolation (no HTTP, no Express).
const { NotFoundError, ValidationError } = require('./errors');

let passed = 0; let failed = 0;
function assert(c, l) {
  if (c) { console.log('  PASS:', l); passed++; }
  else   { console.error('  FAIL:', l); failed++; }
}

// ── GET /users/:id logic ─────────────────────────────────────────────────────
function getUserById(rawId) {
  const id = Number(rawId);
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user ID.', { id: 'Must be a positive integer.' });
  }
  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };
  const user = users[id];
  if (!user) throw new NotFoundError('User');
  return user;
}

console.log('\n=== GET /users/:id ===');
assert(getUserById('1').name === 'Alice', 'id 1 → Alice');
assert(getUserById('2').name === 'Bob',   'id 2 → Bob');

try { getUserById('99'); assert(false, 'missing id should throw'); }
catch (e) {
  assert(e instanceof NotFoundError, 'unknown id → NotFoundError');
  assert(e.statusCode === 404,       'unknown id → 404');
}

try { getUserById('abc'); assert(false, 'bad id should throw'); }
catch (e) {
  assert(e instanceof ValidationError, 'non-numeric id → ValidationError');
  assert(e.statusCode === 422,         'non-numeric id → 422');
  assert(e.fields.id !== undefined,    'fields.id populated');
}

try { getUserById('-5'); assert(false, 'negative id should throw'); }
catch (e) {
  assert(e instanceof ValidationError, 'negative id → ValidationError');
}

try { getUserById('0'); assert(false, 'zero id should throw'); }
catch (e) {
  assert(e instanceof ValidationError, 'zero id → ValidationError');
}

try { getUserById('1.5'); assert(false, 'float id should throw'); }
catch (e) {
  assert(e instanceof ValidationError, 'float id → ValidationError');
}

// ── POST /users logic ────────────────────────────────────────────────────────
function createUser(body) {
  const { name, email } = body ?? {};
  const fieldErrors = {};
  if (!name  || typeof name  !== 'string' || name.trim()  === '') {
    fieldErrors.name = 'Name is required and must be a non-empty string.';
