/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and carries:
 *  - statusCode  – the HTTP status that should be sent to the client
 *  - isOperational – true  → known, expected error (safe to expose message)
 *                    false → programmer/unexpected error (suppress details)
 */

'use strict';

// ─── Base Application Error ──────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message     - Human-readable error description.
   * @param {number}  statusCode  - HTTP status code (default 500).
   * @param {string}  [code]      - Machine-readable error code, e.g. "NOT_FOUND".
   * @param {boolean} [isOperational=true] - Whether the error is expected /
   *                                          safe to expose to the client.
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR', isOperational = true) {
    super(message);

    // Maintain the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace (V8 only, no-op elsewhere).
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── 404 Not Found ───────────────────────────────────────────────────────────

class NotFoundError extends AppError {
  /**
   * Thrown when a requested resource cannot be located.
   *
   * @param {string} [resource] - Optional name of the missing resource,
   *                              e.g. "User" or "/api/unknown".
   *
   * @example
   *   throw new NotFoundError('User');
   *   // → 404  { error: { code: 'NOT_FOUND', message: 'User not found.' } }
   *
   * @example
   *   throw new NotFoundError();
   *   // → 404  { error: { code: 'NOT_FOUND', message: 'Resource not found.' } }
   */
  constructor(resource = 'Resource') {
    super(`${resource} not found.`, 404, 'NOT_FOUND');
  }
}

// ─── 422 Validation Error ────────────────────────────────────────────────────

class ValidationError extends AppError {
  /**
   * Thrown when client-supplied input fails validation rules.
   *
   * @param {string}   message          - Description of the validation failure.
   * @param {Object}   [fields={}]      - Map of field names → per-field messages,
   *                                      useful for form-level feedback.
   *
   * @example
   *   throw new ValidationError('Invalid request body.', {
   *     email: 'Must be a valid e-mail address.',
   *     age:   'Must be a positive integer.',
   *   });
   *   // → 422  { error: { code: 'VALIDATION_ERROR', message: '...', fields: { … } } }
   */
  constructor(message = 'Validation failed.', fields = {}) {
    super(message, 422, 'VALIDATION_ERROR');
    this.fields = fields;
  }
}

// ─── 503 Database Error ──────────────────────────────────────────────────────

class DatabaseError extends AppError {
  /**
   * Thrown when a database operation fails (connection loss, query error, …).
   * The `isOperational` flag is set to `false` so that the error handler
   * suppresses the raw DB message and returns a generic response to the client,
   * while still logging the full details server-side.
   *
   * @param {string} [message]         - Internal description (not sent to client).
   * @param {Error}  [originalError]   - The underlying DB driver error, stored
   *                                     for server-side logging only.
   *
   * @example
   *   throw new DatabaseError('Connection pool exhausted.', pgErr);
   *   // → 503  { error: { code: 'DATABASE_ERROR', message: 'A database error occurred.' } }
   */
  constructor(message = 'A database error occurred.', originalError = null) {
    // isOperational = false → handler will NOT forward the raw message to the client.
    super(message, 503, 'DATABASE_ERROR', false);
    this.originalError = originalError;
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

/**
 * app.js
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 *  Route / middleware
 *    └─ throw AppError subclass  (or next(err) for async handlers)
 *          └─ errorHandler middleware   ← single place for all error responses
 *                └─ sends structured JSON, logs unexpected errors
 */

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

app.use(express.json());

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe — always succeeds while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Demonstrates: normal success path (no errors thrown).
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Demonstrates: NotFoundError when the user does not exist,
 *               ValidationError when the ID is not a valid integer.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user ID.', {
      id: 'Must be a positive integer.',
    });
  }

  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];
  if (!user) {
    throw new NotFoundError('User');
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Demonstrates: ValidationError for missing / malformed fields,
 *               DatabaseError for a simulated persistence failure.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name  || typeof name  !== 'string' || name.trim()  === '') {
    fieldErrors.name = 'Name is required and must be a non-empty string.';
  }
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.email = 'A valid e-mail address is required.';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Invalid request body.', fieldErrors);
  }

  // Simulate a database write failure so DatabaseError handling is exercised.
  // Replace this block with a real persistence call in production.
  const simulateDbFailure = false;
  if (simulateDbFailure) {
    throw new DatabaseError('INSERT query timed out.', new Error('DB timeout'));
  }

  // 201 Created with the new resource representation.
  res.status(201).json({ id: 3, name: name.trim(), email: email.trim() });
});

// ─── 404 Catch-all ───────────────────────────────────────────────────────────
// Must be registered AFTER all valid routes so it only fires for truly unknown
// paths.  Uses next() so the error flows through the standard error handler.

app.use((req, res, next) => {
  next(new NotFoundError(req.originalUrl));
});

// ─── Centralised Error Handler ───────────────────────────────────────────────
// Four-parameter signature is required by Express to recognise this as an
// error-handling middleware.  Must be registered LAST.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Determine whether this is a known operational error ──────────────────
  const isAppError = err instanceof AppError;

  // Default to 500 for anything that slipped through as a plain Error.
  const statusCode = isAppError ? err.statusCode : 500;
  const code       = isAppError ? err.code       : 'INTERNAL_ERROR';

  // ── Server-side logging ───────────────────────────────────────────────────
  // Always log the full stack for unexpected errors.
  // For operational errors only log at a lower severity (warn vs error).
  if (!isAppError || !err.isOperational) {
    console.error('[ERROR] Unexpected error:', err);
    // If the DatabaseError wraps a driver-level error, surface it here too.
    if (err.originalError) {
      console.error('[ERROR] Original cause:', err.originalError);
    }
  } else {
    console.warn(`[WARN] Operational error (${code}):`, err.message);
  }

  // ── Build the client-facing response body ─────────────────────────────────
  // For non-operational / unknown errors suppress the raw message so internal
  // details are never leaked to the client.
  const clientMessage =
    isAppError && err.isOperational
      ? err.message
      : 'An unexpected error occurred. Please try again later.';

  const responseBody = {
    error: {
      code,
      message: clientMessage,
      // Include per-field details only when present (ValidationError).
      ...(err.fields && Object.keys(err.fields).length > 0 && { fields: err.fields }),
    },
  };

  // Attach stack trace in non-production environments to aid debugging.
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    responseBody.error.stack = err.stack;
  }

  res.status(statusCode).json(responseBody);
});

// ─── Server ───────────────────────────────────────────────────────────────────

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

