/**
 * errors.js
 *
 * Centralised custom error classes for the application.
 * Every class extends the base AppError, which carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code sent to the client
 *   - code       – machine-readable error identifier
 *   - isOperational – distinguishes expected (operational) errors from
 *                     unexpected programmer errors so the global handler
 *                     can decide whether to crash the process.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message       - Human-readable error description.
   * @param {number} statusCode    - HTTP status code (e.g. 400, 404, 500).
   * @param {string} code          - Machine-readable error code string.
   * @param {boolean} isOperational - true  → known, handled error (keep running)
   *                                  false → unknown/programmer error (may crash)
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain proper prototype chain for instanceof checks after transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] - Optional name of the missing resource,
   *                              e.g. 'User', 'Order'.  When provided the
   *                              message becomes "User not found."
   */
  constructor(resource = 'Resource') {
    super(
      `${resource} not found.`,
      404,
      'NOT_FOUND',
    );
  }
}

// ---------------------------------------------------------------------------
// 400 – Validation / bad input
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}   message        - Description of what failed validation.
   * @param {Object[]} [errors]       - Optional array of per-field error
   *                                    objects, e.g. from a schema validator.
   *                                    Shape: [{ field, message }, ...]
   */
  constructor(message, errors = []) {
    super(
      message,
      400,
      'VALIDATION_ERROR',
    );

    // Store field-level details so the handler can forward them to the client.
    this.errors = errors;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database / persistence layer error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]    - Defaults to a generic safe message so
   *                                internal details are never leaked to clients.
   * @param {Error}  [cause]      - The original low-level error for server-side
   *                                logging (never sent to the client).
   */
  constructor(message = 'A database error occurred. Please try again later.', cause = null) {
    super(
      message,
      503,
      'DATABASE_ERROR',
    );

    // Store the root cause for internal logging without exposing it externally.
    if (cause) {
      this.cause = cause;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 *
 * Express application with centralised error handling.
 *
 * Request lifecycle
 * ─────────────────
 *  1.  Route handlers do their work and either respond normally or
 *      throw / next() an AppError subclass.
 *  2.  asyncHandler() catches any thrown error (sync or async) and
 *      forwards it to Express's error pipeline via next(err).
 *  3.  notFoundHandler() converts unmatched routes into NotFoundErrors.
 *  4.  globalErrorHandler() is the single place that turns every error
 *      into a consistent JSON response and logs unexpected errors.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Body parsing
// ---------------------------------------------------------------------------
app.use(express.json());

// ---------------------------------------------------------------------------
// Utility: wrap async route handlers so thrown errors reach the error handler
// ---------------------------------------------------------------------------

/**
 * Wraps an async (or sync) route handler and forwards any thrown error to
 * Express's next() so the global error handler can process it.
 *
 * Usage:
 *   app.get('/path', asyncHandler(async (req, res) => { ... }));
 *
 * @param {Function} fn - Express route handler (req, res, next).
 * @returns {Function}  Wrapped handler that catches errors automatically.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – always responds 200.
 */
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
}));

/**
 * GET /users
 * Returns the full list of users.
 * Throws DatabaseError if the data layer fails.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Simulate data retrieval – replace with a real DB call.
  const users = await getUsers();
  res.json(users);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 * Throws ValidationError for a non-numeric id param.
 * Throws NotFoundError when no user matches.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new ValidationError('User ID must be a valid integer.', [
      { field: 'id', message: `'${req.params.id}' is not a valid integer.` },
    ]);
  }

  const user = await getUserById(id);

  if (!user) {
    throw new NotFoundError('User');
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 * Throws ValidationError when required fields are missing or malformed.
 * Throws DatabaseError if persistence fails.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.push({ field: 'email', message: 'email is required and must be a valid email address.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Request body contains invalid or missing fields.', fieldErrors);
  }

  const newUser = await createUser({ name: name.trim(), email: email.trim() });
  res.status(201).json(newUser);
}));

// ---------------------------------------------------------------------------
// Stub data-access helpers
// (Replace these with real database calls; they are here to make the routes
// above self-contained and immediately runnable.)
// ---------------------------------------------------------------------------

const USER_STORE = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

async function getUsers() {
  // Simulate a database interaction; throw DatabaseError on failure.
  try {
    return USER_STORE;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve users.', err);
  }
}

async function getUserById(id) {
  try {
    return USER_STORE.find((u) => u.id === id) ?? null;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve user.', err);
  }
}

async function createUser({ name, email }) {
  try {
    const newUser = { id: USER_STORE.length + 1, name, email };
    USER_STORE.push(newUser);
    return newUser;
  } catch (err) {
    throw new DatabaseError('Failed to create user.', err);
  }
}

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all routes)
// ---------------------------------------------------------------------------

/**
 * Converts any request that falls through all routes into a NotFoundError
 * and forwards it to the global error handler.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl}`));
});

// ---------------------------------------------------------------------------
// Global error-handling middleware  (must come LAST, exactly 4 parameters)
// ---------------------------------------------------------------------------

/**
 * Centralised error handler.
 *
 * Operational errors (AppError subclasses with isOperational = true) are
 * serialised into a consistent JSON envelope and returned to the caller.
 *
 * Unexpected/programmer errors are logged in full and receive a generic
 * 500 response so internal details are never leaked to clients.
 *
 * Response envelope
 * ──────────────────
 * {
 *   "status":  "error",
 *   "code":    "NOT_FOUND",          // machine-readable
 *   "message": "User not found.",    // human-readable
 *   "errors":  [...]                 // optional, ValidationError only
 * }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Operational errors: known AppError subclasses ──────────────────────
  if (err instanceof AppError && err.isOperational) {
    const body = {
      status:  'error',
      code:    err.code,
      message: err.message,
    };

    // Attach field-level details only for validation failures.
    if (err instanceof ValidationError && Array.isArray(err.errors) && err.errors.length > 0) {
      body.errors = err.errors;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Unexpected / programmer errors ────────────────────────────────────
  // Log the full error server-side (stack, cause, etc.) but return only a
  // safe, generic message to the caller.
  console.error('[Unhandled Error]', {
    message:    err.message,
    stack:      err.stack,
    ...(err.cause ? { cause: err.cause } : {}),
    path:       req.originalUrl,
    method:     req.method,
    timestamp:  new Date().toISOString(),
  });

  return res.status(500).json({
    status:  'error',
    code:    'INTERNAL_SERVER_ERROR',
    message: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT ?? 3000;

/* istanbul ignore next */
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

