    assert('correct name',           u1.body.name === 'Alice');

    console.log('\n── GET /users/999 (not found) ───────────────');
    const u999 = await get('/users/999');
    assert('status 404',             u999.status === 404);
    assert('code NOT_FOUND',         u999.body.code === 'NOT_FOUND');
