/**
 * errors.js
 *
 * Centralised custom error classes.
 * Every class extends the built-in Error so that:
 *  - instanceof checks work correctly across the whole app
 *  - stack traces are captured automatically
 *  - the Express error-handling middleware can branch on error type
 */

'use strict';

// ─── Base Application Error ───────────────────────────────────────────────────

/**
 * AppError
 *
 * The root class for all application-level errors.
 * Carries an HTTP status code and an optional `isOperational` flag that
 * distinguishes expected domain errors (true) from unexpected programmer
 * errors (false).  The centralised middleware uses this flag to decide
 * whether to expose details to the client.
 */
class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable description.
   * @param {number}  statusCode     - HTTP status code to send to the client.
   * @param {string}  [code]         - Machine-readable error code (e.g. "NOT_FOUND").
   * @param {boolean} [isOperational=true] - true → safe to expose to client.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain the correct prototype chain for instanceof
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code || this.constructor.name.toUpperCase();
    this.isOperational = isOperational;

    // Capture a clean stack trace that omits this constructor call
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── Concrete Error Classes ───────────────────────────────────────────────────

/**
 * NotFoundError  →  404
 *
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Order ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [code='NOT_FOUND']
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

/**
 * ValidationError  →  400
 *
 * Thrown when input data fails business-rule or schema validation.
 * An optional `fields` map can carry per-field error details that the
 * client can use to highlight form fields.
 *
 * @example
 *   throw new ValidationError('Invalid email address');
 *   throw new ValidationError('Validation failed', 'INVALID_INPUT', {
 *     email: 'Must be a valid email',
 *     age:   'Must be a positive integer',
 *   });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Validation failed']
   * @param {string} [code='VALIDATION_ERROR']
   * @param {Object} [fields={}] - Map of field name → error message.
   */
  constructor(message = 'Validation failed', code = 'VALIDATION_ERROR', fields = {}) {
    super(message, 400, code);
    this.fields = fields;
  }
}

/**
 * DatabaseError  →  503
 *
 * Thrown when a database operation fails (connection lost, query error, etc.).
 * Marked as non-operational by default so the middleware logs it fully and
 * returns a safe generic message rather than leaking query details.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted');
 *   throw new DatabaseError(`Query failed: ${err.message}`, 'DB_QUERY_ERROR');
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {string} [code='DATABASE_ERROR']
   */
  constructor(message = 'A database error occurred', code = 'DATABASE_ERROR') {
    // isOperational = false → middleware will hide the real message from clients
    super(message, 503, code, false);
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 *
 * Express application with centralised error-handling middleware.
 * Routes signal errors exclusively by throwing (or passing via next()) custom
 * error instances defined in errors.js — no inline res.status().json() for
 * error paths anywhere in the route layer.
 */

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();
app.use(express.json());

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe — always succeeds if the process is up.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns all users.
 * Throws DatabaseError if the data layer is unavailable.
 */
app.get('/users', (req, res, next) => {
  try {
    // Simulated data layer — replace with real DB calls.
    const users = fetchAllUsers();
    res.json(users);
  } catch (err) {
    next(err);   // forward to centralised error handler
  }
});

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Throws:
 *  - ValidationError  when :id is not a positive integer
 *  - NotFoundError    when no user matches :id
 *  - DatabaseError    propagated from the data layer
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        'User ID must be a positive integer',
        'INVALID_USER_ID',
        { id: 'Must be a positive integer' }
      );
    }

    const user = fetchUserById(id);

    if (!user) {
      throw new NotFoundError(`User with ID ${id} not found`, 'USER_NOT_FOUND');
    }

    res.json(user);
  } catch (err) {
    next(err);
  }
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws:
 *  - ValidationError  when required fields are missing or malformed
 *  - DatabaseError    propagated from the data layer
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;
    const fieldErrors = {};

    if (!name || typeof name !== 'string' || name.trim() === '') {
      fieldErrors.name = 'Name is required and must be a non-empty string';
    }

    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      fieldErrors.email = 'A valid email address is required';
    }

    if (Object.keys(fieldErrors).length > 0) {
      throw new ValidationError('Request body validation failed', 'INVALID_USER_INPUT', fieldErrors);
    }

    const newUser = createUser({ name: name.trim(), email: email.trim() });
    res.status(201).json(newUser);
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /users/:id
 * Deletes a user by numeric ID.
 *
 * Throws:
 *  - ValidationError  when :id is not a positive integer
 *  - NotFoundError    when no user matches :id
 *  - DatabaseError    propagated from the data layer
 */
app.delete('/users/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        'User ID must be a positive integer',
        'INVALID_USER_ID',
        { id: 'Must be a positive integer' }
      );
    }

    const deleted = deleteUser(id);

    if (!deleted) {
      throw new NotFoundError(`User with ID ${id} not found`, 'USER_NOT_FOUND');
    }

    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

// ─── 404 catch-all (must come after all real routes) ─────────────────────────

/**
 * Forwards any request that reached no route as a NotFoundError so it flows
 * through the same centralised error handler as every other error.
 */
