// These stand-in functions keep the module self-contained.
// Replace them with real database calls; throw DatabaseError on failure.

let userStore = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

function fetchAllUsers() {
  // Example: throw new DatabaseError('Connection refused'); // on DB failure
  return userStore;
}

function fetchUserById(id) {
  // Example: throw new DatabaseError('Query timeout');      // on DB failure
  return userStore.find((u) => u.id === id) || null;
}

function createUser({ name, email }) {
  const newUser = { id: userStore.length + 1, name, email };
  userStore.push(newUser);
  return newUser;
}

function deleteUser(id) {
  const index = userStore.findIndex((u) => u.id === id);
