'use strict';
const http  = require('http');
const app   = require('./app');

const server = http.createServer(app);
server.listen(0, '127.0.0.1', () => {
  const { port } = server.address();
  const base = `http://127.0.0.1:${port}`;

  const cases = [
    // ── Happy paths ────────────────────────────────────────────────────────
    { label: 'GET  /health               → 200', method: 'GET',    path: '/health' },
    { label: 'GET  /users                → 200', method: 'GET',    path: '/users' },
    { label: 'GET  /users/1              → 200', method: 'GET',    path: '/users/1' },
    { label: 'POST /users (valid)        → 201', method: 'POST',   path: '/users',
      body: JSON.stringify({ name: 'Carol', email: 'carol@example.com' }),
      headers: { 'Content-Type': 'application/json' } },
    { label: 'DEL  /users/1              → 204', method: 'DELETE', path: '/users/1' },

    // ── Error paths ────────────────────────────────────────────────────────
    { label: 'GET  /users/0              → 400 ValidationError',  method: 'GET',    path: '/users/0' },
    { label: 'GET  /users/abc            → 400 ValidationError',  method: 'GET',    path: '/users/abc' },
    { label: 'GET  /users/999            → 404 NotFoundError',    method: 'GET',    path: '/users/999' },
    { label: 'POST /users (missing body) → 400 ValidationError',  method: 'POST',   path: '/users',
      body: JSON.stringify({}),
      headers: { 'Content-Type': 'application/json' } },
    { label: 'POST /users (bad email)    → 400 ValidationError',  method: 'POST',   path: '/users',
      body: JSON.stringify({ name: 'Dan', email: 'not-an-email' }),
      headers: { 'Content-Type': 'application/json' } },
    { label: 'DEL  /users/999            → 404 NotFoundError',    method: 'DELETE', path: '/users/999' },
    { label: 'GET  /nonexistent          → 404 NotFoundError',    method: 'GET',    path: '/nonexistent' },
  ];

  let pending = cases.length;
  const results = [];

  cases.forEach(({ label, method, path, body, headers = {} }) => {
    const options = { method, headers };
    const req = http.request(`${base}${path}`, options, (res) => {
      let raw = '';
      res.on('data', (c) => (raw += c));
      res.on('end', () => {
        const parsed = raw ? JSON.parse(raw) : null;
        results.push({ label, status: res.statusCode, body: parsed });
        if (--pending === 0) finish();
      });
    });
    req.on('error', (e) => { results.push({ label, error: e.message }); if (--pending === 0) finish(); });
    if (body) req.write(body);
    req.end();
  });

  function finish() {
    server.close();
    results.forEach(({ label, status, body, error }) => {
      if (error) { console.log(`FAIL  ${label}\n      ERROR: ${error}`); return; }
      const preview = body
        ? (body.error ? `code=${body.error.code}` : JSON.stringify(body).slice(0, 60))
        : '(no body)';
      console.log(`${status >= 400 ? (body && body.error ? 'PASS' : 'FAIL') : 'PASS'}  [${status}] ${label}`);
      if (body && body.error) console.log(`        └─ ${preview}`);
    });
  }
});
EOF

