  /**
   * @param {string}  message        - Human-readable description.
   * @param {number}  statusCode     - HTTP status code to send to the client.
   * @param {string}  [code]         - Machine-readable error code (e.g. "NOT_FOUND").
   * @param {boolean} [isOperational=true] - true → safe to expose to client.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain the correct prototype chain for instanceof
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code || this.constructor.name.toUpperCase();
    this.isOperational = isOperational;

    // Capture a clean stack trace that omits this constructor call
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
