/**
 * errors.js
 *
 * Centralised error hierarchy for the Express application.
 *
 * Every custom error extends AppError, which carries three extra fields that
 * the error-handling middleware in app.js relies on:
 *
 *   statusCode  – HTTP status sent to the client.
 *   errorCode   – Machine-readable string identifier (useful for API clients).
 *   isOperational – true  → expected / handled error; log at warn level.
 *                   false → programmer error;         log at error level and
 *                           consider restarting the process.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message        Human-readable description.
   * @param {number} statusCode     HTTP status code (e.g. 404).
   * @param {string} errorCode      Snake-cased machine identifier (e.g. 'not_found').
   * @param {boolean} isOperational Whether this is an expected operational error.
   */
  constructor(message, statusCode, errorCode, isOperational = true) {
    super(message);

    // Maintains proper stack trace in V8 (Node / Chrome).
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.errorCode   = errorCode;
    this.isOperational = isOperational;

    // ISO timestamp for structured logging.
    this.timestamp = new Date().toISOString();
  }

  /**
   * Serialise to a plain object suitable for JSON responses.
   * Sensitive internals (stack, isOperational) are intentionally omitted.
   */
  toJSON() {
    return {
      error: {
        name:      this.name,
        code:      this.errorCode,
        message:   this.message,
        status:    this.statusCode,
        timestamp: this.timestamp,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] Optional resource name/identifier that was not found.
   *
   * @example
   *   throw new NotFoundError('User with id 42');
   *   // → 404  { error: { code: 'not_found', message: 'User with id 42 was not found.' } }
   *
   *   throw new NotFoundError();
   *   // → 404  { error: { code: 'not_found', message: 'The requested resource was not found.' } }
   */
  constructor(resource) {
    const message = resource
      ? `${resource} was not found.`
      : 'The requested resource was not found.';

    super(message, 404, 'not_found');
  }
}

// ---------------------------------------------------------------------------
// 422 Validation Error
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}              message Human-readable summary.
   * @param {Record<string,string>} [fields] Per-field error map, e.g.
   *                                         { email: 'must be a valid email address' }
   *
   * @example
   *   throw new ValidationError('Invalid request body', {
   *     email: 'must be a valid email address',
   *     age:   'must be a positive integer',
   *   });
   */
  constructor(message = 'Validation failed.', fields = {}) {
    super(message, 422, 'validation_error');
    // Per-field details are attached separately so callers can inspect them.
    this.fields = fields;
  }

  /** Extend the base serialisation to include per-field details. */
  toJSON() {
    const base = super.toJSON();
    if (Object.keys(this.fields).length > 0) {
      base.error.fields = this.fields;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 Database Error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]  Human-readable summary (defaults to a generic message so
   *                            raw DB driver messages are never leaked to the client).
   * @param {Error}  [cause]    Original error from the database driver.  It is stored on
   *                            the instance so it can be logged server-side, but it is
   *                            never included in the JSON response sent to clients.
   *
   * @example
   *   try {
   *     await db.query(sql);
   *   } catch (err) {
   *     throw new DatabaseError('Could not load users.', err);
   *   }
   */
  constructor(
    message = 'A database error occurred. Please try again later.',
    cause   = null,
  ) {
    // DatabaseError is still operational (expected at runtime) but treated as
    // a server-side fault, hence 503 Service Unavailable.
    super(message, 503, 'database_error');

    if (cause) {
      // Node 16.9+ supports the native `cause` option; we also set it manually
      // for compatibility with older runtimes.
      this.cause = cause;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Global middleware
// ---------------------------------------------------------------------------

// Parse JSON request bodies; reject payloads larger than 10 KB.
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded form bodies (e.g. HTML forms).
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Liveness probe — always returns 200 while the process is alive.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns a list of all users.
 *
 * Simulated error path: pass ?fail=db   to trigger a DatabaseError.
 */
app.get('/users', (req, res) => {
  // ── Simulated failure hook (remove in production) ──────────────────────
  if (req.query.fail === 'db') {
    throw new DatabaseError(
      'Could not retrieve users.',
      new Error('Simulated connection timeout'),
    );
  }
  // ───────────────────────────────────────────────────────────────────────

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric id.
 *
 * Throws:
 *   ValidationError – if :id is not a positive integer.
 *   NotFoundError   – if no user exists with that id.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user identifier.', {
      id: 'must be a positive integer',
    });
  }

  // Simulated data store.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id}`);
  }

  res.json(user);
});

/**
 * POST /users
 *
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Throws:
 *   ValidationError – if required fields are missing or malformed.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'is required and must be a non-empty string';
  }

  if (!email || typeof email !== 'string') {
    fieldErrors.email = 'is required and must be a string';
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.email = 'must be a valid email address';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Invalid request body.', fieldErrors);
  }

  // Simulate successful creation (no real persistence layer here).
  const newUser = { id: 3, name: name.trim(), email };
  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// 404 catch-all — must come AFTER all valid routes
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError(`${req.method} ${req.path}`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
//
// Express identifies error-handling middleware by its four-parameter signature
// (err, req, res, next).  It MUST be registered last.
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Normalise the error ───────────────────────────────────────────────

  // If the error is already one of our custom AppErrors, use it as-is.
  // Otherwise wrap unknown/programmer errors in a generic AppError so the
  // rest of the handler can treat everything uniformly.
  const isAppError = err instanceof AppError;

  // Express body-parser emits errors with a `type` field and a `status` of
  // 400.  Promote those to ValidationErrors so clients get a clear message.
  if (!isAppError && err.type === 'entity.parse.failed') {
    return res
      .status(400)
      .json(
        new ValidationError(
          'Request body contains malformed JSON.',
        ).toJSON(),
      );
  }

  // ── 2. Determine the response status ────────────────────────────────────
  const statusCode = isAppError ? err.statusCode : 500;

  // ── 3. Log the error server-side ────────────────────────────────────────
  // Operational errors (expected failures like 404/422) → warn level.
  // Programmer errors (unexpected) → error level with full stack.
  const isOperational = isAppError && err.isOperational;

  if (isOperational) {
    console.warn(
      `[${err.timestamp}] WARN  ${err.name} (${err.errorCode}) — ${err.message}`,
    );
    // Log the original cause of a DatabaseError without leaking it to clients.
    if (err.cause) {
      console.warn('  Caused by:', err.cause.message);
    }
  } else {
    console.error(
      `[${new Date().toISOString()}] ERROR Unexpected error on ${req.method} ${req.path}`,
    );
    console.error(err);
  }

  // ── 4. Build the response body ───────────────────────────────────────────
  // For operational AppErrors use the structured toJSON() serialisation.
  // For unexpected errors send a generic 500 message — never leak internals.
  const body = isAppError
    ? err.toJSON()
    : {
        error: {
          name:      'InternalServerError',
          code:      'internal_server_error',
          message:   'An unexpected error occurred. Please try again later.',
          status:    500,
          timestamp: new Date().toISOString(),
        },
      };

  // ── 5. Send the response ─────────────────────────────────────────────────
  // Guard against trying to send headers after they have already been flushed
  // (e.g. a streaming route that errored mid-stream).
  if (res.headersSent) {
    return next(err);
  }

  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

