/**
 * errors.js
 *
 * Centralised application error classes.
 *
 * Every class extends the built-in Error so that:
 *   - instanceof checks work correctly throughout the codebase
 *   - stack traces are preserved
 *   - Express's error-handling middleware can inspect `err.statusCode`
 *     and `err.code` without any extra branching logic
 *
 * Usage (inside a route or service):
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required', [{ field: 'email', message: 'required' }]);
 *   throw new DatabaseError('Connection timed out');
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError is the root class for all custom errors in this application.
 *
 * @property {number}  statusCode - HTTP status code sent to the client.
 * @property {string}  code       - Machine-readable error identifier used in
 *                                  JSON responses (e.g. "NOT_FOUND").
 * @property {boolean} isOperational - Distinguishes expected operational
 *                                     errors (true) from unexpected programmer
 *                                     bugs (false).  The global error handler
 *                                     uses this flag to decide whether to
 *                                     expose the message to the client.
 */
class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description of the error.
   * @param {number}  statusCode    - HTTP status code (default 500).
   * @param {string}  code          - Machine-readable error code.
   * @param {boolean} isOperational - Whether this is an expected operational
   *                                  error (default true).
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_SERVER_ERROR', isOperational = true) {
    super(message);

    // Restore the prototype chain so instanceof works after transpilation
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not here
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error into a plain object safe to send as a JSON response.
   * Sensitive internals (stack trace) are intentionally omitted.
   *
   * @returns {{ error: { code: string, message: string } }}
   */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * HTTP status: 404
 * Code:        NOT_FOUND
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message - Defaults to a generic "Resource not found" message.
   */
  constructor(message = 'Resource not found') {
    super(message, 404, 'NOT_FOUND');
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when client-supplied input fails validation rules.
 *
 * HTTP status: 422 (Unprocessable Entity)
 * Code:        VALIDATION_ERROR
 *
 * Carries an optional `details` array so that callers can communicate
 * field-level validation failures alongside the top-level message.
 *
 * @example
 *   throw new ValidationError('Invalid request body', [
 *     { field: 'email',    message: 'Must be a valid email address' },
 *     { field: 'password', message: 'Must be at least 8 characters' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   message          - Summary of what failed validation.
   * @param {Array<{ field: string, message: string }>} [details=[]]
   *                                    - Per-field validation failures.
   */
  constructor(message = 'Validation failed', details = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.details = details;
  }

  /**
   * Extends the base serialisation to include per-field `details`.
   *
   * @returns {{ error: { code: string, message: string, details: Array } }}
   */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
        details: this.details,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails (connection refused, query error,
 * timeout, constraint violation, etc.).
 *
 * HTTP status: 503 (Service Unavailable) – chosen over 500 to signal that
 *              the failure is infrastructure-related and may be transient,
 *              allowing clients / proxies to retry automatically.
