      console.error('[CAUSE]', err.cause);
    }
  } else {
    // In production only log the error code and a sanitised message
    console.error(`[ERROR] ${err.name} (${err.statusCode ?? 500}): ${err.message}`);
  }

  // ── 2. Determine response shape ──────────────────────────────────────────
  if (err instanceof AppError) {
    // Known operational error — the error class owns its own serialisation
    return res.status(err.statusCode).json(err.toJSON());
  }

  // Unexpected / programmer error (e.g. a plain TypeError thrown accidentally)
  // Do NOT leak internal details to the client.
  return res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: isDev
        ? err.message  // helpful during development
        : 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap  (skipped when the module is required in tests)
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

