/**
 * errors.js
 *
 * Centralised custom error classes for the Express application.
 * Every class extends the built-in Error so that:
 *   - instanceof checks work correctly up the prototype chain
 *   - stack traces are captured at the throw-site
 *   - the error middleware can branch purely on `err.statusCode`
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError is the root class for all known, intentional errors thrown by the
 * application.  It is never thrown directly — use one of the subclasses below.
 *
 * Properties available on every AppError instance:
 *   message     {string}  – human-readable description (forwarded to Error)
 *   statusCode  {number}  – HTTP status code to send to the client
 *   code        {string}  – stable machine-readable identifier, safe to expose
 *   isOperational {bool}  – true  → predictable runtime condition (send detail)
 *                           false → programming bug (log only, hide detail)
 */
class AppError extends Error {
  /**
   * @param {string} message       Human-readable error description.
   * @param {number} statusCode    HTTP status code (e.g. 400, 404, 500).
   * @param {string} code          Machine-readable code  (e.g. 'NOT_FOUND').
   * @param {boolean} isOperational Whether this is an expected runtime error.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct constructor name in the prototype chain so that
    // subclass names appear in stack traces instead of "Error".
    this.name = this.constructor.name;

    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean V8 stack trace that starts at the throw-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Throw when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'user');
 *   // → 404  { error: { code: 'NOT_FOUND', message: 'User not found',
 *   //                    resource: 'user' } }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message    Description of what was not found.
   * @param {string} [resource] Optional resource type label (e.g. 'user').
   */
  constructor(message = 'Resource not found', resource = null) {
    super(message, 404, 'NOT_FOUND');
    this.resource = resource;
  }
}

// ---------------------------------------------------------------------------
// 400 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Throw when request input fails validation.
 *
 * @example
 *   throw new ValidationError('Invalid email address', [
 *     { field: 'email', message: 'Must be a valid email' },
 *   ]);
 *   // → 400  { error: { code: 'VALIDATION_ERROR', message: '…',
 *   //                    details: [ { field, message } ] } }
 */
class ValidationError extends AppError {
  /**
   * @param {string}   message            Top-level summary of what is invalid.
   * @param {Array}    [details=[]]       Per-field validation failures.
   *                                      Each entry: { field, message }.
   */
  constructor(message = 'Validation failed', details = []) {
    super(message, 400, 'VALIDATION_ERROR');
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * Throw when a database operation fails in an expected way (e.g. connection
 * refused, query timeout, constraint violation that was not caught earlier).
 *
 * The error is marked as operational so that the middleware returns a
 * structured 503 instead of a generic 500, while still masking raw database
 * internals from clients in production.
 *
 * @example
 *   throw new DatabaseError('Failed to fetch users');
 *   // → 503  { error: { code: 'DATABASE_ERROR', message: '…' } }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} message       High-level description safe to show clients.
   * @param {Error}  [original]    The original low-level error for server logs.
   */
  constructor(message = 'A database error occurred', original = null) {
    super(message, 503, 'DATABASE_ERROR');
    // Store the original error for logging purposes only — never send it to
    // the client.
    this.original = original;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

// ---------------------------------------------------------------------------
// Dependencies
// ---------------------------------------------------------------------------

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// In-memory data store (stand-in for a real database layer)
// ---------------------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness check — always succeeds.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns all users.
 *
 * Throws:
 *   DatabaseError – if the data store is unavailable (simulated via query
 *                   param ?fail=1 for testing purposes).
 */
app.get('/users', (req, res) => {
  // Simulate a database failure so the DatabaseError path can be exercised.
  if (req.query.fail) {
    throw new DatabaseError('Failed to retrieve users from the database');
  }

  res.json(USERS);
});

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Throws:
 *   ValidationError – if :id is not a positive integer.
 *   NotFoundError   – if no user exists with that ID.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id < 1) {
    throw new ValidationError('Invalid user ID', [
      { field: 'id', message: 'Must be a positive integer' },
    ]);
  }

  const user = USERS.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with ID ${id} not found`, 'user');
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws:
 *   ValidationError – if required fields are missing or malformed.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const validationIssues = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    validationIssues.push({ field: 'name', message: 'Name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    validationIssues.push({ field: 'email', message: 'A valid email address is required' });
  }

  if (validationIssues.length > 0) {
    throw new ValidationError('User creation failed due to invalid input', validationIssues);
  }

  const newUser = { id: USERS.length + 1, name: name.trim(), email };
  USERS.push(newUser);

  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all real routes)
// ---------------------------------------------------------------------------

/**
 * Any request that does not match a defined route reaches this handler.
 * We throw (not call next) so that the single error-handling middleware below
 * is responsible for formatting the response.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * Express identifies error-handling middleware by its four-parameter signature
 * (err, req, res, next).  All errors — whether thrown synchronously in a route
 * handler or passed via next(err) — end up here.
 *
 * Behaviour:
 *   • Operational errors (AppError subclasses, isOperational=true):
 *       Log a concise warning and return the structured JSON body below.
 *   • Unknown / programming errors (isOperational=false, or plain Error):
 *       Log the full stack for debugging and return a generic 500 so that
 *       internal details are never leaked to the client.
 *
 * Response shape (all errors):
 * {
 *   "error": {
 *     "code":    "NOT_FOUND",            // machine-readable, stable
 *     "message": "User … not found",     // human-readable
 *     // ── optional, type-specific fields ──────────────────────────────
 *     "details":  [ { "field": "…", "message": "…" } ],  // ValidationError
 *     "resource": "user"                                   // NotFoundError
 *   }
 * }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Operational errors ─────────────────────────────────────────────────
  if (err instanceof AppError && err.isOperational) {
    // Safe to log a brief summary; no raw internals escape to the client.
    console.warn(`[${err.code}] ${req.method} ${req.path} → ${err.message}`);

    const body = {
      error: {
        code:    err.code,
        message: err.message,
      },
    };

    // Attach type-specific supplementary fields when present.
    if (err instanceof ValidationError && err.details.length > 0) {
      body.error.details = err.details;
    }

    if (err instanceof NotFoundError && err.resource) {
      body.error.resource = err.resource;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Unknown / programmer errors ────────────────────────────────────────
  // Log the full stack so engineers can diagnose the issue, but send only a
  // generic message to the client to avoid leaking implementation details.
  console.error('[UNHANDLED ERROR]', err);

  return res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

