const nf = new NotFoundError();
const ve = new ValidationError('bad input');
const de = new DatabaseError('timeout');

console.assert(nf instanceof Error,    'NotFoundError instanceof Error');
console.assert(nf instanceof AppError, 'NotFoundError instanceof AppError');
console.assert(ve instanceof AppError, 'ValidationError instanceof AppError');
console.assert(de instanceof AppError, 'DatabaseError instanceof AppError');

