'use strict';
const request = require('http');

// ── Start the app ─────────────────────────────────────────────────────────
process.env.NODE_ENV = 'test';
process.env.PORT     = '3099';
const app = require('./app');
const server = app.listen(3099);

// Helper: fire an HTTP request, resolve with { statusCode, body }
function get(path) {
  return new Promise((resolve, reject) => {
    request.get({ host: 'localhost', port: 3099, path }, (res) => {
      let raw = '';
      res.on('data', d => raw += d);
      res.on('end', () => {
        try { resolve({ statusCode: res.statusCode, body: JSON.parse(raw) }); }
        catch (e) { resolve({ statusCode: res.statusCode, body: raw }); }
      });
    }).on('error', reject);
  });
}

function post(path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const opts = {
      host: 'localhost', port: 3099, path,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) },
    };
    const req = request.request(opts, (res) => {
      let raw = '';
      res.on('data', d => raw += d);
      res.on('end', () => {
        try { resolve({ statusCode: res.statusCode, body: JSON.parse(raw) }); }
        catch (e) { resolve({ statusCode: res.statusCode, body: raw }); }
      });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function run() {
  const checks = [];

  // 1. GET /health → 200
  const health = await get('/health');
  checks.push(['GET /health → 200',           health.statusCode === 200]);
  checks.push(['health body has status:ok',   health.body.status === 'ok']);

  // 2. GET /users → 200 with array
  const users = await get('/users');
  checks.push(['GET /users → 200',            users.statusCode === 200]);
  checks.push(['users body is array',         Array.isArray(users.body)]);

  // 3. GET /users/1 → 200 Alice
  const alice = await get('/users/1');
  checks.push(['GET /users/1 → 200',          alice.statusCode === 200]);
