/**
 * errors.js
 *
 * Centralised custom error classes for the Express application.
 *
 * All classes extend AppError, which itself extends the native Error so that:
 *  - instanceof checks work correctly throughout the codebase.
 *  - Every error carries a consistent { statusCode, code, message } shape.
 *  - The centralised error-handling middleware in app.js can handle every
 *    error through a single, predictable code-path.
 *
 * Usage (inside a route or service):
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required');
 *   throw new DatabaseError('Connection timed out');
 */

'use strict';

// ─── Base class ──────────────────────────────────────────────────────────────

/**
 * AppError
 *
 * The root of the custom error hierarchy. All application-specific errors
 * should extend this class rather than the native Error so that the
 * centralised middleware can distinguish them from unexpected programmer errors.
 *
 * @param {string} message     - Human-readable description of the problem.
 * @param {number} statusCode  - HTTP status code to be sent to the client.
 * @param {string} code        - A machine-readable error identifier (snake_case).
 */
class AppError extends Error {
  constructor(message, statusCode, code) {
    super(message);

    // Maintain the correct class name in stack traces.
    this.name = this.constructor.name;

    // HTTP status code that the error handler should forward to the client.
    this.statusCode = statusCode;

    // Machine-readable code for programmatic consumers (e.g. front-end logic,
    // logging pipelines, or test assertions).
    this.code = code;

    // Flag that lets the error handler distinguish "expected" operational
    // errors (safe to expose to the client) from unexpected ones.
    this.isOperational = true;

    // Capture a clean stack trace that begins at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── Concrete error classes ───────────────────────────────────────────────────

/**
 * NotFoundError  →  HTTP 404
 *
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   */
  constructor(message = 'Resource not found') {
    super(message, 404, 'NOT_FOUND');
  }
}

/**
 * ValidationError  →  HTTP 400
 *
 * Thrown when incoming request data fails validation (missing fields,
 * wrong types, constraint violations, etc.).
 *
 * @example
 *   throw new ValidationError('Email address is required');
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Invalid request data']
   */
  constructor(message = 'Invalid request data') {
    super(message, 400, 'VALIDATION_ERROR');
  }
}

/**
 * DatabaseError  →  HTTP 503
 *
 * Thrown when a database operation fails (connection error, query failure,
 * constraint violation that was not caught earlier, etc.).
 *
 * Note: a 503 (Service Unavailable) is preferred over 500 because the
 * application itself is healthy — it is the backing store that is
 * temporarily unavailable.
 *
 * @example
 *   throw new DatabaseError('Connection to database timed out');
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   */
  constructor(message = 'A database error occurred') {
    super(message, 503, 'DATABASE_ERROR');
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 *
 * Express application entry-point.
 *
 * Error-handling strategy
 * ───────────────────────
 * Routes never call res.status().json() directly for error conditions.
 * Instead they throw (or, for async handlers, pass to next()) an instance of
 * one of the custom error classes defined in errors.js.
 *
 * Two pieces of middleware placed at the bottom of the middleware stack take
 * care of all error responses:
 *
 *   1. 404 handler  – catches requests that matched no route.
 *   2. Global error handler – formats every AppError (and unexpected errors)
 *      into a consistent JSON envelope and sets the correct HTTP status code.
 */

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

// ─── Request parsing ──────────────────────────────────────────────────────────

app.use(express.json());

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Liveness probe — always returns 200 while the process is alive.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns the full list of users.
 *
 * Demonstrates: a route that succeeds under normal circumstances but throws a
 * DatabaseError if the data layer is unavailable.
 */
app.get('/users', (req, res) => {
  // Simulated data layer — replace with a real DB call.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Example guard: if the data layer returns nothing at all, treat it as a
  // database-level failure rather than an empty result-set.
  if (!users) {
    throw new DatabaseError('Failed to retrieve users from the database');
  }

  res.json(users);
});

/**
 * GET /users/:id
 *
 * Returns a single user by id.
 *
 * Demonstrates:
 *  - ValidationError when :id is not a positive integer.
 *  - NotFoundError  when no user matches the given id.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  // Validate that the caller supplied a usable identifier.
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(`User id must be a positive integer, received: "${req.params.id}"`);
  }

  // Simulated data layer — replace with a real DB call.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`);
  }

  res.json(user);
});

/**
 * POST /users
 *
 * Creates a new user.
 *
 * Demonstrates: ValidationError for missing or malformed request body fields.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    throw new ValidationError('Field "name" is required and must be a non-empty string');
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    throw new ValidationError('Field "email" is required and must be a valid email address');
  }

  // Simulated persistence — replace with a real DB call.
  const newUser = { id: Date.now(), name: name.trim(), email: email.trim() };

  res.status(201).json(newUser);
});

// ─── 404 handler ─────────────────────────────────────────────────────────────
//
// Must be registered AFTER all valid routes so it only fires when nothing
// above matched the incoming request.

app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`));
});

// ─── Global error handler ─────────────────────────────────────────────────────
//
// Express identifies this as an error-handling middleware because it declares
// exactly four parameters (err, req, res, next).  It must be the LAST piece of
// middleware registered.
//
// Response envelope:
// {
//   "status":  "error",
//   "code":    "NOT_FOUND",          // machine-readable, from AppError.code
//   "message": "User … not found"    // human-readable, from Error.message
// }
//
// In production the stack trace is omitted from the response body to avoid
// leaking internal implementation details to clients; it is still written to
// stderr so it is captured by log aggregators.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Determine status code ────────────────────────────────────────────────
  // Prefer the status code carried by the error itself; fall back to 500 for
  // anything that is not an operational AppError (e.g. programmer mistakes or
  // third-party library exceptions).
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // ── Log the error ────────────────────────────────────────────────────────
  // Always log to stderr so the problem is visible in server logs regardless
  // of whether we expose the detail to the HTTP client.
  if (statusCode >= 500) {
    console.error(`[ERROR] ${err.stack ?? err.message}`);
  } else {
    // 4xx errors are operational and expected; a single-line warning suffices.
    console.warn(`[WARN]  ${err.message} (${statusCode})`);
  }

  // ── Build the response body ──────────────────────────────────────────────
  const body = {
    status:  'error',
    code:    err.code    ?? 'INTERNAL_SERVER_ERROR',
    message: err.message ?? 'An unexpected error occurred',
  };

  // Attach the stack trace only in non-production environments so developers
  // get full context during local development and CI runs.
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    body.stack = err.stack;
  }

  res.status(statusCode).json(body);
});

// ─── Start server ─────────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

