/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the base AppError, which carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code sent to the client
 *   - code       – machine-readable string for programmatic handling
 *   - isOperational – true  → expected/safe error (log as warning)
 *                     false → programmer mistake (log as critical)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message       - Human-readable error message.
   * @param {number} statusCode    - HTTP status code (default 500).
   * @param {string} code          - Machine-readable error code.
   * @param {boolean} isOperational - Whether this is a "safe" operational error.
   */
  constructor(
    message,
    statusCode = 500,
    code = 'INTERNAL_ERROR',
    isOperational = true,
  ) {
    super(message);

    // Maintain proper prototype chain so `instanceof` checks work correctly
    // across transpilation boundaries.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = new.target.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not inside
    // this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /** Serialise the error to a plain object suitable for a JSON response. */
  toJSON() {
    return {
      error: {
        code: this.code,
        message: this.message,
        statusCode: this.statusCode,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'user');
 *   // { code: 'USER_NOT_FOUND', statusCode: 404 }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message    - Human-readable description (default generic).
   * @param {string} [resource] - Optional resource name used to build the code.
   */
  constructor(message = 'Resource not found', resource = null) {
    const code = resource
      ? `${resource.toUpperCase()}_NOT_FOUND`
      : 'NOT_FOUND';

    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when request input fails validation.
 * Carries an optional `fields` map so callers can pinpoint which fields failed.
 *
 * @example
 *   throw new ValidationError('Invalid email address', { email: 'Must be a valid email' });
 *   // { code: 'VALIDATION_ERROR', statusCode: 422, fields: { email: '...' } }
 */
class ValidationError extends AppError {
  /**
   * @param {string} message            - Human-readable description.
   * @param {Object} [fields={}]        - Map of field names to error messages.
   * @param {string} [code]             - Optional override for the error code.
   */
  constructor(
    message = 'Validation failed',
    fields = {},
    code = 'VALIDATION_ERROR',
  ) {
    super(message, 422, code);
    // Shallow-clone so the caller's object cannot be mutated after the fact.
    this.fields = { ...fields };
  }

  toJSON() {
    const base = super.toJSON();
    // Only attach `fields` when there is something meaningful to report.
    if (Object.keys(this.fields).length > 0) {
      base.error.fields = this.fields;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when an interaction with the database fails.
 * Marked as non-operational by default because a DB failure is not expected
 * during normal operation — callers can override this if they wrap a known
 * transient error (e.g. a connection timeout).
 *
 * @example
 *   throw new DatabaseError('Connection refused');
 *   // { code: 'DATABASE_ERROR', statusCode: 503 }
 */
class DatabaseError extends AppError {
  /**
   * @param {string}  message        - Human-readable description.
   * @param {Error}   [cause]        - The original low-level error, if any.
   * @param {boolean} [isOperational=false] - Override to true for expected
   *                                          transient failures.
   */
  constructor(
    message = 'A database error occurred',
    cause = null,
    isOperational = false,
  ) {
    super(message, 503, 'DATABASE_ERROR', isOperational);
    if (cause instanceof Error) {
      // Store the original error for server-side logging without leaking it to
      // the client.
      this.cause = cause;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * routes/health.js
 * Health-check endpoint.
 */

'use strict';

const { Router } = require('express');

const router = Router();

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------

/**
 * Returns a simple liveness signal.
 * No async I/O, so no error paths are needed here; the global middleware
 * will still catch anything unexpected.
 */
router.get('/', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

module.exports = router;

/**
 * routes/users.js
 * User-related endpoints.
 *
 * All error paths use `throw` (or `next(err)` inside async handlers) so that
 * the centralised error middleware in app.js handles every response
 * consistently — no inline res.status().json() for errors anywhere.
 */

'use strict';

const { Router } = require('express');
const { NotFoundError, ValidationError } = require('../errors');

const router = Router();

// ---------------------------------------------------------------------------
// In-memory data store (replace with real DB layer as needed)
// ---------------------------------------------------------------------------

let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Returns the next available integer ID. */
const nextId = () =>
  users.length > 0 ? Math.max(...users.map((u) => u.id)) + 1 : 1;

/**
 * Validates the fields required to create / update a user.
 *
 * @param {Object}  body
 * @param {boolean} [requireAll=true] - false for partial (PATCH) updates.
 * @throws {ValidationError}
 */
function validateUserBody(body, requireAll = true) {
  const fields = {};

  if (requireAll && !body.name) {
    fields.name = 'name is required';
  } else if (body.name !== undefined) {
    if (typeof body.name !== 'string' || body.name.trim() === '') {
      fields.name = 'name must be a non-empty string';
    }
  }

  if (requireAll && !body.email) {
    fields.email = 'email is required';
  } else if (body.email !== undefined) {
    // Simple RFC-5322 surface check — swap for a real validator in production.
    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRe.test(body.email)) {
      fields.email = 'email must be a valid email address';
    }
  }

  if (Object.keys(fields).length > 0) {
    throw new ValidationError('Request body validation failed', fields);
  }
}

// ---------------------------------------------------------------------------
// GET /users — list all users
// ---------------------------------------------------------------------------

router.get('/', (req, res) => {
  res.json(users);
});

// ---------------------------------------------------------------------------
// GET /users/:id — fetch a single user
// ---------------------------------------------------------------------------

router.get('/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Validation failed', {
      id: 'id must be a positive integer',
    });
  }

  const user = users.find((u) => u.id === id);
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'user');
  }

  res.json(user);
});

// ---------------------------------------------------------------------------
// POST /users — create a new user
// ---------------------------------------------------------------------------

router.post('/', (req, res) => {
  validateUserBody(req.body, true);

  const newUser = {
    id: nextId(),
    name: req.body.name.trim(),
    email: req.body.email.trim(),
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// PUT /users/:id — full replacement of an existing user
// ---------------------------------------------------------------------------

router.put('/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Validation failed', {
      id: 'id must be a positive integer',
    });
  }

  validateUserBody(req.body, true);

  const index = users.findIndex((u) => u.id === id);
  if (index === -1) {
    throw new NotFoundError(`User with id ${id} not found`, 'user');
  }

  users[index] = { id, name: req.body.name.trim(), email: req.body.email.trim() };
  res.json(users[index]);
});

// ---------------------------------------------------------------------------
// PATCH /users/:id — partial update of an existing user
// ---------------------------------------------------------------------------

router.patch('/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Validation failed', {
      id: 'id must be a positive integer',
    });
  }

  validateUserBody(req.body, false);

  const index = users.findIndex((u) => u.id === id);
  if (index === -1) {
    throw new NotFoundError(`User with id ${id} not found`, 'user');
  }

  if (req.body.name) users[index].name = req.body.name.trim();
  if (req.body.email) users[index].email = req.body.email.trim();
  res.json(users[index]);
});

// ---------------------------------------------------------------------------
// DELETE /users/:id — remove a user
// ---------------------------------------------------------------------------

router.delete('/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Validation failed', {
      id: 'id must be a positive integer',
    });
  }

  const index = users.findIndex((u) => u.id === id);
  if (index === -1) {
    throw new NotFoundError(`User with id ${id} not found`, 'user');
  }

  users.splice(index, 1);
  res.status(204).send();
});

module.exports = router;

/**
 * middleware/errorHandler.js
 * Centralised Express error-handling middleware.
 *
 * Must be registered LAST (after all routes) with exactly four parameters so
 * Express recognises it as an error handler.
 *
 * Behaviour
 * ─────────
 *  • AppError subclasses (operational errors) → structured JSON + their own
 *    statusCode, logged at WARN level.
 *  • Unknown / programmer errors               → 500 JSON, logged at ERROR
 *    level (full stack exposed only in non-production environments).
 *  • Request-body parse errors from express.json() → re-wrapped as
 *    ValidationError so the client gets a consistent shape.
 */

'use strict';

const { AppError, ValidationError } = require('../errors');

// ---------------------------------------------------------------------------
// Minimal structured logger (swap for Winston / Pino in production)
// ---------------------------------------------------------------------------

const log = {
  warn: (msg, meta) =>
    console.warn(JSON.stringify({ level: 'WARN', msg, ...meta })),
  error: (msg, meta) =>
    console.error(JSON.stringify({ level: 'ERROR', msg, ...meta })),
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const isProd = process.env.NODE_ENV === 'production';

/**
 * Coerces well-known third-party / Express errors into AppError subclasses
 * so they receive a consistent JSON shape.
 *
