/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the base AppError, which carries:
 *   - statusCode  → the HTTP status sent to the client
 *   - isOperational → distinguishes expected errors (true) from
 *                     unexpected programming bugs (false) so the
 *                     global handler can decide whether to expose
 *                     details or log aggressively.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message        - Human-readable description of the error.
   * @param {number} statusCode     - HTTP status code to return to the client.
   * @param {string} [errorCode]    - Machine-readable code, e.g. "NOT_FOUND".
   * @param {boolean} [isOperational=true] - false for unexpected/programming errors.
   */
  constructor(message, statusCode, errorCode, isOperational = true) {
    super(message);

    // Maintain the correct prototype chain so `instanceof` checks work.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.errorCode   = errorCode || 'INTERNAL_ERROR';
    this.isOperational = isOperational;

    // Capture a clean stack trace (V8 only; no-op on other engines).
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', 'user');
 *   // → 404  { error: { code: 'NOT_FOUND', message: 'User not found', resource: 'user' } }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found'] - Override default message.
   * @param {string} [resource]                     - Name of the missing resource type.
   */
  constructor(message = 'Resource not found', resource) {
    super(message, 404, 'NOT_FOUND');
    this.resource = resource || null;
  }
}

// ---------------------------------------------------------------------------
// 422 Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when the client sends data that fails validation rules.
 *
 * @example
 *   throw new ValidationError('Invalid email address', [
 *     { field: 'email', message: 'Must be a valid email' },
 *   ]);
 *   // → 422  { error: { code: 'VALIDATION_ERROR', message: '…', fields: […] } }
 */
class ValidationError extends AppError {
  /**
   * @param {string}   [message='Validation failed'] - Override default message.
   * @param {Array<{field: string, message: string}>} [fields=[]]
   *   Per-field validation failures for detailed client feedback.
   */
  constructor(message = 'Validation failed', fields = []) {
    super(message, 422, 'VALIDATION_ERROR');
    // `fields` lets callers surface per-field detail without extra parsing.
    this.fields = Array.isArray(fields) ? fields : [fields];
  }
}

// ---------------------------------------------------------------------------
// 503 Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails in an unexpected way.
 * Marked as non-operational by default because a database error is
 * often a sign of infrastructure problems that warrant loud alerting.
 *
 * @example
 *   throw new DatabaseError('Connection timed out', originalDbErr);
 *   // → 503  { error: { code: 'DATABASE_ERROR', message: 'Connection timed out' } }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred'] - Override default message.
   * @param {Error}  [originalError]  - The raw error from the DB driver/ORM,
   *   stored on the instance for internal logging but never sent to the client.
   */
  constructor(message = 'A database error occurred', originalError) {
    // isOperational = false: treat as a serious infrastructure failure.
    super(message, 503, 'DATABASE_ERROR', false);
    if (originalError instanceof Error) {
      this.originalError = originalError;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

