// ---------------------------------------------------------------------------
// Body parsing
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – always succeeds.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns a static list of users.
 * Demonstrates a happy-path route with no error conditions.
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 * Throws NotFoundError when the id does not match any record.
 * Throws ValidationError when the id is not a positive integer.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user id', [
      { field: 'id', message: 'Must be a positive integer' },
    ]);
  }

  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'user');
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user (stubbed – no persistence layer yet).
 * Throws ValidationError when required fields are absent or malformed.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body || {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'email is required and must be a valid address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Validation failed', fieldErrors);
  }

  // Stub: echo the new user back with a fake generated id.
  const newUser = { id: Date.now(), name: name.trim(), email };
  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must be registered AFTER all real routes)
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

