  const statusCode = isAppError ? err.statusCode : 500;
  const errorCode  = isAppError ? err.errorCode  : 'INTERNAL_ERROR';

  // ── 2. Logging ────────────────────────────────────────────────────────────
  // Operational errors (expected domain failures) are info-level noise.
  // Non-operational errors (bugs, infra failures) deserve a full stack trace.
