    // Operational errors are still worth recording, just less urgently.
    console.warn(`[WARN] Operational error (${statusCode} ${errorCode}): ${err.message}`);
  }

  // ── 3. Build response payload ─────────────────────────────────────────────
  const payload = {
    error: {
      code:    errorCode,
      message: err.message || 'An unexpected error occurred',
    },
  };

