# Verify the class hierarchy and core properties at runtime
node -e "
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// --- inheritance ---
const nfe = new NotFoundError('User not found', 'user');
console.assert(nfe instanceof AppError,      'NotFoundError extends AppError');
console.assert(nfe instanceof NotFoundError, 'NotFoundError instanceof itself');
console.assert(nfe.statusCode === 404,       'NotFoundError statusCode 404');
console.assert(nfe.errorCode  === 'NOT_FOUND', 'NotFoundError errorCode');
console.assert(nfe.resource   === 'user',    'NotFoundError resource');
console.assert(nfe.isOperational === true,   'NotFoundError isOperational');

const ve = new ValidationError('Bad input', [{ field: 'email', message: 'invalid' }]);
console.assert(ve instanceof AppError,          'ValidationError extends AppError');
console.assert(ve.statusCode === 422,           'ValidationError statusCode 422');
console.assert(ve.errorCode  === 'VALIDATION_ERROR', 'ValidationError errorCode');
console.assert(ve.fields.length === 1,          'ValidationError fields length');
console.assert(ve.isOperational === true,       'ValidationError isOperational');

const original = new Error('pg timeout');
const dbe = new DatabaseError('Connection failed', original);
console.assert(dbe instanceof AppError,         'DatabaseError extends AppError');
console.assert(dbe.statusCode === 503,          'DatabaseError statusCode 503');
console.assert(dbe.errorCode  === 'DATABASE_ERROR', 'DatabaseError errorCode');
console.assert(dbe.isOperational === false,     'DatabaseError isOperational false');
console.assert(dbe.originalError === original,  'DatabaseError stores originalError');

// --- defaults ---
const def = new NotFoundError();
console.assert(def.message === 'Resource not found', 'NotFoundError default message');
console.assert(def.resource === null,                'NotFoundError default resource null');

console.log('All error-class assertions passed.');
"

# Spin up the server on a random port, exercise every route, then kill the server
node -e "
process.env.PORT = '0';          // let the OS pick a free port
process.env.NODE_ENV = 'test';
const app = require('./app');
const http = require('http');

const server = http.createServer(app);
server.listen(0, '127.0.0.1', async () => {
  const { port } = server.address();
  const base = 'http://127.0.0.1:' + port;

  async function request(method, path, body) {
    const opts = {
      method,
      headers: body ? { 'content-type': 'application/json' } : {},
    };
    const url = new URL(path, base);
    return new Promise((resolve, reject) => {
      const req = http.request(url, opts, res => {
        let data = '';
        res.on('data', d => (data += d));
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(data) }));
      });
      req.on('error', reject);
      if (body) req.write(JSON.stringify(body));
      req.end();
    });
  }

  const results = [];

  function check(label, condition) {
    results.push(condition ? '  PASS  ' + label : '  FAIL  ' + label);
  }

  // ── GET /health ──────────────────────────────────────────────────────────
  let r = await request('GET', '/health');
  check('GET /health → 200',          r.status === 200);
  check('GET /health body.status=ok', r.body.status === 'ok');

  // ── GET /users ───────────────────────────────────────────────────────────
  r = await request('GET', '/users');
  check('GET /users → 200',        r.status === 200);
  check('GET /users returns array', Array.isArray(r.body));

  // ── GET /users/:id  (found) ───────────────────────────────────────────────
  r = await request('GET', '/users/1');
  check('GET /users/1 → 200',        r.status === 200);
  check('GET /users/1 name=Alice',   r.body.name === 'Alice');

  // ── GET /users/:id  (not found) ───────────────────────────────────────────
  r = await request('GET', '/users/99');
  check('GET /users/99 → 404',           r.status === 404);
  check('GET /users/99 code=NOT_FOUND',  r.body.error.code === 'NOT_FOUND');
  check('GET /users/99 resource=user',   r.body.error.resource === 'user');

  // ── GET /users/:id  (bad id) ──────────────────────────────────────────────
  r = await request('GET', '/users/abc');
  check('GET /users/abc → 422',               r.status === 422);
  check('GET /users/abc code=VALIDATION_ERR', r.body.error.code === 'VALIDATION_ERROR');
  check('GET /users/abc has fields',          Array.isArray(r.body.error.fields));

  // ── POST /users (valid) ────────────────────────────────────────────────────
  r = await request('POST', '/users', { name: 'Carol', email: 'carol@example.com' });
  check('POST /users valid → 201',    r.status === 201);
  check('POST /users body.name',      r.body.name === 'Carol');

  // ── POST /users (missing fields) ──────────────────────────────────────────
  r = await request('POST', '/users', {});
  check('POST /users empty → 422',             r.status === 422);
  check('POST /users empty code=VAL_ERR',      r.body.error.code === 'VALIDATION_ERROR');
  check('POST /users empty has 2 field errs',  r.body.error.fields.length === 2);

  // ── POST /users (bad email only) ──────────────────────────────────────────
  r = await request('POST', '/users', { name: 'Dave', email: 'not-an-email' });
  check('POST /users bad-email → 422',        r.status === 422);
  check('POST /users bad-email field=email',  r.body.error.fields[0].field === 'email');

  // ── 404 catch-all ─────────────────────────────────────────────────────────
  r = await request('GET', '/no-such-route');
  check('GET /no-such-route → 404',          r.status === 404);
  check('GET /no-such-route code=NOT_FOUND', r.body.error.code === 'NOT_FOUND');

  // ── Report ────────────────────────────────────────────────────────────────
  results.forEach(l => console.log(l));
  const failed = results.filter(l => l.includes('FAIL'));
  console.log('');
  if (failed.length === 0) {
    console.log('All route smoke-tests passed ✓');
  } else {
    console.error(failed.length + ' test(s) FAILED');
    process.exit(1);
  }

  server.close();
});
"

