/**
 * errors.js
 *
 * Centralised custom error classes for the Express application.
 *
 * All classes extend AppError, which itself extends the native Error so that
 * instanceof checks, stack traces, and JSON serialisation all work correctly
 * throughout the codebase.
 *
 * Usage in a route:
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required', [{ field: 'email', message: 'required' }]);
 *   throw new DatabaseError('Query failed');
 *
 * The centralised error-handling middleware in app.js reads the statusCode /
 * details properties and converts them into a consistent JSON response.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * Base class for all application-level errors.
 *
 * @property {number}  statusCode  - HTTP status code to send to the client.
 * @property {string}  code        - Machine-readable error code (e.g. "NOT_FOUND").
 * @property {boolean} isOperational
 *   true  → known, expected error (invalid input, missing resource, …).
 *           The middleware will expose the message to the client.
 *   false → unexpected programming error.
 *           The middleware will return a generic "Internal Server Error" message
 *           and log the real details server-side.
 */
class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description.
   * @param {number}  statusCode    - HTTP status code.
   * @param {string}  code          - Machine-readable error identifier.
   * @param {boolean} isOperational - Whether the error was anticipated.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain correct prototype chain so `instanceof AppError` works after
    // transpilation (TypeScript / Babel quirk, harmless in plain Node).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not inside
    // this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error to a plain object suitable for a JSON response body.
   * Subclasses may override this to include extra fields (e.g. `details`).
   *
   * @returns {{ error: string, message: string, statusCode: number }}
   */
  toJSON() {
    return {
      error:      this.code,
      message:    this.message,
      statusCode: this.statusCode,
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * NotFoundError
 *
 * Throw when a requested resource cannot be located.
 *
 * HTTP status: 404
 * Code:        "NOT_FOUND"
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 *   // → { error: 'NOT_FOUND', message: 'User with id 42 not found', statusCode: 404 }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found'] - Optional custom message.
   */
  constructor(message = 'Resource not found') {
    super(message, 404, 'NOT_FOUND');
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * ValidationError
 *
 * Throw when request input fails validation (missing fields, wrong types, …).
 *
 * HTTP status: 422
 * Code:        "VALIDATION_ERROR"
 *
 * @example
 *   throw new ValidationError('Invalid request body', [
 *     { field: 'email',    message: 'must be a valid email address' },
 *     { field: 'username', message: 'is required' },
 *   ]);
 *   // → {
 *   //     error: 'VALIDATION_ERROR',
 *   //     message: 'Invalid request body',
 *   //     statusCode: 422,
 *   //     details: [ … ]
 *   //   }
 */
class ValidationError extends AppError {
  /**
   * @param {string}                                       [message='Validation failed']
   * @param {Array<{ field: string, message: string }>}   [details=[]]
   *   Optional list of per-field validation failures for structured clients.
   */
  constructor(message = 'Validation failed', details = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.details = details;
  }

  /** @override – includes `details` array in the response body. */
  toJSON() {
    return {
      ...super.toJSON(),
      details: this.details,
    };
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * DatabaseError
 *
 * Throw when a database operation fails in a way that the route handler can
 * detect and wants to surface as a typed error (e.g. a unique-constraint
 * violation that maps to a user-facing message).
 *
 * For truly unexpected DB crashes, let the raw error bubble up to the
 * middleware, which will treat it as a 500 Internal Server Error.
 *
 * HTTP status: 503
 * Code:        "DATABASE_ERROR"
 *
 * @example
 *   throw new DatabaseError('Unable to reach the database');
