node -e "
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// --- instanceof chain ---
const nf = new NotFoundError();
const ve = new ValidationError('bad', [{ field: 'x', message: 'y' }]);
const de = new DatabaseError('db down', new Error('original'));

console.assert(nf instanceof AppError,       'NotFoundError extends AppError');
console.assert(nf instanceof NotFoundError,  'NotFoundError instanceof');
console.assert(ve instanceof AppError,       'ValidationError extends AppError');
console.assert(de instanceof AppError,       'DatabaseError extends AppError');

// --- statusCodes ---
