console.assert(ve.code === 'VALIDATION_ERROR',  'ValidationError code');
console.assert(de.code === 'DATABASE_ERROR',    'DatabaseError code');

// --- isOperational ---
console.assert(nf.isOperational === true, 'all operational');
console.assert(ve.isOperational === true, 'all operational');
console.assert(de.isOperational === true, 'all operational');

// --- toJSON shapes ---
const nfJSON = nf.toJSON();
console.assert(nfJSON.error === 'NOT_FOUND',   'toJSON error field');
console.assert(nfJSON.statusCode === 404,      'toJSON statusCode field');
console.assert('message' in nfJSON,            'toJSON message field');

const veJSON = ve.toJSON();
console.assert(Array.isArray(veJSON.details),  'ValidationError toJSON has details');
console.assert(veJSON.details[0].field === 'x','ValidationError details field');

// --- DatabaseError cause stored ---
console.assert(de.cause instanceof Error, 'DatabaseError.cause stored');

// --- default messages ---
console.assert(new NotFoundError().message === 'Resource not found',         'NotFoundError default msg');
console.assert(new ValidationError().message === 'Validation failed',        'ValidationError default msg');
console.assert(new DatabaseError().message === 'A database error occurred',  'DatabaseError default msg');

console.log('All error class assertions passed');
"

