 * Behaviour:
 *
 *  1. AppError subclasses (NotFoundError, ValidationError, DatabaseError)
 *     → isOperational === true
 *     → Use the error's own statusCode and toJSON() output.
 *     → Message is safe to expose to the client.
 *
 *  2. Any other Error (programming mistakes, unexpected library failures)
 *     → isOperational === false (or not an AppError at all)
 *     → Always returns 500.
 *     → Logs the full error server-side.
 *     → Returns a generic message to the client so internal details are not leaked.
 *
 *  3. The X-Request-ID header is echoed back when present so distributed
 *     tracing can correlate logs with responses without extra tooling.
 *
 * @param {Error}             err
 * @param {express.Request}   req
 * @param {express.Response}  res
 * @param {express.NextFunction} _next  - Required by Express; intentionally unused.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  // ── 1. Determine whether this is a known operational error ──────────────
  const isOperational = err instanceof AppError && err.isOperational;

  // ── 2. Always log the full error for server-side observability ──────────
  //    In a real app swap this for a structured logger (pino, winston, …).
  const requestId = req.headers['x-request-id'] ?? 'n/a';
  console.error(
    `[${new Date().toISOString()}] requestId=${requestId} ` +
    `${err.name ?? 'Error'}: ${err.message}`,
    // Only include the stack trace for unexpected errors to keep logs tidy
    isOperational ? '' : err.stack
  );

  // ── 3. Build the response payload ──────────────────────────────────────
  const statusCode = isOperational ? err.statusCode : 500;

  const body = isOperational
    ? err.toJSON()
    : {
        error:      'INTERNAL_SERVER_ERROR',
        message:    'An unexpected error occurred. Please try again later.',
        statusCode: 500,
      };

  // ── 4. Optionally echo the request-id so callers can correlate logs ─────
  if (requestId !== 'n/a') {
    res.set('X-Request-ID', requestId);
  }

  res.status(statusCode).json(body);
});

