const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── AppError base ──────────────────────────────────────────────────────────
const base = new AppError('Something went wrong', 500, 'INTERNAL_ERROR');
console.assert(base instanceof Error,     'AppError extends Error');
console.assert(base instanceof AppError,  'instanceof AppError');
console.assert(base.statusCode  === 500,  'statusCode 500');
console.assert(base.errorCode   === 'INTERNAL_ERROR', 'errorCode');
console.assert(base.isOperational === true, 'isOperational true');
const baseJSON = base.toJSON();
console.assert(baseJSON.error.message === 'Something went wrong', 'toJSON message');
console.assert(!('details' in baseJSON.error), 'no details key when meta is null');

// ── NotFoundError ──────────────────────────────────────────────────────────
const nfe = new NotFoundError('Widget');
console.assert(nfe instanceof AppError,     'NotFoundError extends AppError');
console.assert(nfe instanceof NotFoundError,'instanceof NotFoundError');
console.assert(nfe.statusCode === 404,      'statusCode 404');
console.assert(nfe.errorCode  === 'NOT_FOUND', 'errorCode NOT_FOUND');
console.assert(nfe.message    === 'Widget not found.', 'message interpolation');
console.assert(nfe.toJSON().error.name === 'NotFoundError', 'toJSON name');

// default resource name
const nfeDefault = new NotFoundError();
console.assert(nfeDefault.message === 'Resource not found.', 'default resource');

// ── ValidationError ────────────────────────────────────────────────────────
const fields = [{ field: 'email', issue: 'Invalid email.' }];
const ve = new ValidationError('Bad input.', fields);
console.assert(ve instanceof AppError,        'ValidationError extends AppError');
console.assert(ve instanceof ValidationError, 'instanceof ValidationError');
console.assert(ve.statusCode === 422,         'statusCode 422');
console.assert(ve.errorCode  === 'VALIDATION_ERROR', 'errorCode');
const veJSON = ve.toJSON();
console.assert(Array.isArray(veJSON.error.details), 'details is array');
console.assert(veJSON.error.details[0].field === 'email', 'details field');

// no fieldErrors variant
const veSimple = new ValidationError('Oops.');
console.assert(veSimple.toJSON().error.details === undefined, 'no details when null');

// ── DatabaseError ──────────────────────────────────────────────────────────
const cause = new Error('pg: connection refused');
const dbe = new DatabaseError('DB unavailable.', cause);
console.assert(dbe instanceof AppError,     'DatabaseError extends AppError');
console.assert(dbe instanceof DatabaseError,'instanceof DatabaseError');
console.assert(dbe.statusCode === 503,      'statusCode 503');
console.assert(dbe.errorCode  === 'DATABASE_ERROR', 'errorCode');
console.assert(dbe.cause === cause,         'cause stored');
// cause must NOT appear in the JSON response
const dbeJSON = JSON.stringify(dbe.toJSON());
console.assert(!dbeJSON.includes('pg: connection refused'), 'cause not leaked in JSON');

// default message
const dbeDefault = new DatabaseError();
console.assert(dbeDefault.message.includes('database error'), 'default db message');

console.log('errors.js – all assertions passed ✓');
"

