const http  = require('http');
const app   = require('./app');

const server = http.createServer(app);
server.listen(0, '127.0.0.1', async () => {
  const { address, port } = server.address();
  const base = \`http://\${address}:\${port}\`;

  async function req(method, path, body) {
    const opts = {
      method,
      headers: { 'Content-Type': 'application/json' },
    };
    return new Promise((resolve) => {
      const r = http.request(base + path, opts, (res) => {
        let data = '';
        res.on('data', (c) => (data += c));
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(data) }));
      });
      if (body) r.write(JSON.stringify(body));
      r.end();
    });
  }

  const tests = [];

  // ── GET /health ─────────────────────────────────────────────────────────
  {
    const r = await req('GET', '/health');
    tests.push(['GET /health → 200',          r.status === 200]);
    tests.push(['/health has status:ok',       r.body.status === 'ok']);
  }

  // ── GET /users ───────────────────────────────────────────────────────────
  {
    const r = await req('GET', '/users');
    tests.push(['GET /users → 200',            r.status === 200]);
    tests.push(['/users returns array',        Array.isArray(r.body)]);
    tests.push(['/users has 2 items',          r.body.length === 2]);
  }

  // ── GET /users/:id – happy path ───────────────────────────────────────
  {
    const r = await req('GET', '/users/1');
    tests.push(['GET /users/1 → 200',          r.status === 200]);
    tests.push(['/users/1 name = Alice',       r.body.name === 'Alice']);
  }

  // ── GET /users/:id – not found ────────────────────────────────────────
  {
    const r = await req('GET', '/users/99');
    tests.push(['GET /users/99 → 404',         r.status === 404]);
    tests.push(['/users/99 code NOT_FOUND',    r.body.error.code === 'NOT_FOUND']);
    tests.push(['/users/99 name NotFoundError',r.body.error.name === 'NotFoundError']);
  }

  // ── GET /users/:id – invalid id ───────────────────────────────────────
  {
    const r = await req('GET', '/users/abc');
    tests.push(['GET /users/abc → 422',        r.status === 422]);
    tests.push(['/users/abc code VALIDATION',  r.body.error.code === 'VALIDATION_ERROR']);
    tests.push(['details array present',       Array.isArray(r.body.error.details)]);
  }

  // ── POST /users – happy path ─────────────────────────────────────────
  {
    const r = await req('POST', '/users', { name: 'Carol', email: 'carol@example.com' });
    tests.push(['POST /users → 201',           r.status === 201]);
    tests.push(['new user has name Carol',     r.body.name === 'Carol']);
  }

  // ── POST /users – missing fields ──────────────────────────────────────
  {
    const r = await req('POST', '/users', {});
    tests.push(['POST /users {} → 422',        r.status === 422]);
    tests.push(['validation details for name', r.body.error.details.some(d => d.field === 'name')]);
    tests.push(['validation details for email',r.body.error.details.some(d => d.field === 'email')]);
  }

  // ── POST /users – bad email ───────────────────────────────────────────
  {
    const r = await req('POST', '/users', { name: 'Dave', email: 'not-an-email' });
    tests.push(['POST /users bad email → 422', r.status === 422]);
    tests.push(['details mentions email',      r.body.error.details.some(d => d.field === 'email')]);
  }

  // ── 404 catch-all ─────────────────────────────────────────────────────
  {
    const r = await req('GET', '/does-not-exist');
    tests.push(['unknown route → 404',         r.status === 404]);
    tests.push(['catch-all code NOT_FOUND',    r.body.error.code === 'NOT_FOUND']);
  }

  // ── Malformed JSON body ────────────────────────────────────────────────
  {
    const r = await new Promise((resolve) => {
      const opts = { method: 'POST', headers: { 'Content-Type': 'application/json' } };
      const req2 = http.request(base + '/users', opts, (res) => {
        let d = ''; res.on('data', c => d += c);
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(d) }));
      });
      req2.write('{bad json');
      req2.end();
    });
    tests.push(['malformed JSON → 400',        r.status === 400]);
    tests.push(['malformed JSON has error obj', 'error' in r.body]);
  }

  // ── Print results ──────────────────────────────────────────────────────
  let passed = 0, failed = 0;
  for (const [label, ok] of tests) {
    const icon = ok ? '✓' : '✗';
    console.log(\`  \${icon}  \${label}\`);
    ok ? passed++ : failed++;
  }
  console.log(\`\napp.js integration – \${passed} passed, \${failed} failed\`);

  server.close();
  if (failed > 0) process.exit(1);
});
"

