/**
 * errors.js
 *
 * Centralised custom error classes for the application.
 * Every class extends the built-in Error so that:
 *   - instanceof checks work correctly
 *   - Stack traces are captured automatically
 *   - Express's error-handling middleware can inspect `statusCode`
 *     and `isOperational` without any extra logic.
 *
 * Usage (in a route or service):
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required');
 *   throw new DatabaseError('Query failed');
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * The root class for all known, intentional errors.
 *
 * @property {number}  statusCode   - HTTP status code sent to the client.
 * @property {string}  code         - Machine-readable error identifier.
 * @property {boolean} isOperational - true  → expected/handled error (4xx, etc.)
 *                                     false → programming/unexpected error (5xx)
 */
class AppError extends Error {
  /**
   * @param {string} message     - Human-readable description of the error.
   * @param {number} statusCode  - HTTP status code (default 500).
   * @param {string} code        - Stable string identifier (e.g. 'NOT_FOUND').
   * @param {boolean} isOperational - Whether this is a known, handled error.
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR', isOperational = true) {
    super(message);

    // Restore the prototype chain (required when extending built-ins in ES5
    // transpiled output; harmless in native ES6+).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = new.target.name; // e.g. "NotFoundError"
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Resource not found
// ---------------------------------------------------------------------------

/**
 * NotFoundError
 *
 * Throw when a requested resource cannot be located.
 *
 * HTTP 404 Not Found
 *
 * @example
 *   const user = await User.findById(id);
 *   if (!user) throw new NotFoundError(`User ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message] - Defaults to 'Resource not found'.
   */
  constructor(message = 'Resource not found') {
    super(message, 404, 'NOT_FOUND', true);
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation / bad input
// ---------------------------------------------------------------------------

/**
 * ValidationError
 *
 * Throw when user-supplied data fails business-rule or schema validation.
 * Prefer 422 (Unprocessable Entity) over 400 so clients can distinguish
 * "I couldn't parse the body at all" (400) from "the data is structurally
 * correct but semantically invalid" (422).
 *
 * HTTP 422 Unprocessable Entity
 *
 * @example
 *   if (!email) throw new ValidationError('email is required');
 *   if (errors.length) throw new ValidationError('Invalid payload', errors);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   [message] - Defaults to 'Validation failed'.
   * @param {Array}    [errors]  - Optional array of per-field error objects,
   *                               e.g. [{ field: 'email', message: 'required' }].
   */
  constructor(message = 'Validation failed', errors = []) {
    super(message, 422, 'VALIDATION_ERROR', true);
    // Attach the optional field-level detail so the middleware can forward it.
    this.errors = errors;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database / persistence error
// ---------------------------------------------------------------------------

/**
 * DatabaseError
 *
 * Throw when a persistence-layer operation fails in an unexpected way
 * (connection lost, query timeout, constraint violation that the app could
 * not predict, etc.).
 *
 * HTTP 503 Service Unavailable – signals to the client that the problem is
 * transient and a retry may succeed.
 *
 * IMPORTANT: Never include raw database error messages in the `message`
 * parameter for production responses; sanitise them before constructing
 * this error to avoid leaking schema details.
 *
 * @example
 *   try {
 *     await db.query(sql);
 *   } catch (err) {
 *     throw new DatabaseError('Could not retrieve users', err);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]  - Defaults to 'A database error occurred'.
   * @param {Error}  [original] - The underlying driver error (kept server-side
   *                              only; never serialised into the HTTP response).
   */
  constructor(message = 'A database error occurred', original = null) {
    super(message, 503, 'DATABASE_ERROR', true);
    // Store the raw cause for server-side logging without exposing it to
    // clients via the error-handling middleware.
    this.original = original;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 *
 * Express application entry point.
 *
 * Error handling strategy
 * ───────────────────────
 * Routes never call res.status().json() for error cases directly.
 * Instead they throw (sync) or call next(err) (async) so that the single
 * centralised error-handling middleware at the bottom of this file owns
 * every error response.  This keeps route handlers focused on the happy
 * path and makes error-response shape consistent across the whole API.
 *
 *   Operational errors  (NotFoundError / ValidationError / DatabaseError)
 *     → logged at warn level, meaningful message forwarded to the client.
 *
 *   Unexpected errors   (anything else / isOperational === false)
 *     → logged at error level with full stack, generic message to client
 *       so internal details are never leaked.
 */

'use strict';

const express = require('express');

const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Body parsing
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers (inline demo data — replace with real DB/service calls)
// ---------------------------------------------------------------------------

/** Simulated user store used by the demo routes below. */
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

/**
 * Looks up a user by id.
 * Throws DatabaseError when the store is unavailable (simulated),
 * or NotFoundError when the user does not exist.
 *
 * @param {number} id
 * @returns {{ id: number, name: string, email: string }}
 */
function findUserById(id) {
  // Simulate an unexpected DB outage for id === 0 so the DatabaseError
  // path can be exercised during manual testing.
  if (id === 0) {
    throw new DatabaseError(
      'Could not retrieve user — connection timeout',
      new Error('ETIMEDOUT'), // raw driver error, kept server-side only
    );
  }

  const user = USERS.find((u) => u.id === id);
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`);
  }
  return user;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe — always returns 200 while the process is up.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── Users ────────────────────────────────────────────────────────────────────

/**
 * GET /users
 * Returns the full list of users.
 *
 * Error scenarios:
 *   - If the backing store becomes unavailable a DatabaseError propagates
 *     to the centralised error handler via next(err).
 */
app.get('/users', (req, res, next) => {
  try {
    // In a real app this would be an async DB call; wrap it the same way.
    res.json(USERS);
  } catch (err) {
    // Any unexpected persistence error bubbles up to the error middleware.
    next(err);
  }
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Error scenarios:
 *   - Non-numeric id          → ValidationError (422)
 *   - User not found          → NotFoundError   (404)
 *   - DB connection failure   → DatabaseError   (503)
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id < 0) {
      throw new ValidationError('User id must be a non-negative integer', [
        { field: 'id', message: 'Must be a non-negative integer' },
      ]);
    }

    const user = findUserById(id);
    res.json(user);
  } catch (err) {
    next(err);
  }
});

/**
 * POST /users
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Error scenarios:
 *   - Missing / blank name    → ValidationError (422)
 *   - Missing / blank email   → ValidationError (422)
 *   - Duplicate email         → ValidationError (422)
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body ?? {};
    const fieldErrors = [];

    if (!name  || typeof name  !== 'string' || name.trim()  === '') {
      fieldErrors.push({ field: 'name',  message: 'name is required and must be a non-empty string' });
    }
    if (!email || typeof email !== 'string' || email.trim() === '') {
      fieldErrors.push({ field: 'email', message: 'email is required and must be a non-empty string' });
    }

    if (fieldErrors.length > 0) {
      throw new ValidationError('Invalid user payload', fieldErrors);
    }

    // Duplicate-email guard.
    if (USERS.some((u) => u.email === email.trim())) {
      throw new ValidationError('A user with this email already exists', [
        { field: 'email', message: 'Must be unique' },
      ]);
    }

    const newUser = { id: USERS.length + 1, name: name.trim(), email: email.trim() };
    USERS.push(newUser);

    res.status(201).json(newUser);
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all real routes)
// ---------------------------------------------------------------------------

/**
 * Catch-all for any URL that did not match a registered route.
 * Delegates immediately to the error-handling middleware by throwing
 * a NotFoundError, keeping the error-response format consistent.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Express identifies this as an error-handling middleware because it declares
 * four parameters (err, req, res, next).  It MUST be registered last.
 *
 * Behaviour
 * ─────────
 *  1. Operational errors  (AppError subclasses with isOperational === true)
 *       Logged at warn level.  The error's own statusCode and message are
 *       forwarded to the client, along with any extra detail (e.g. field
 *       errors from ValidationError).
 *
 *  2. Unexpected / programmer errors  (everything else)
 *       Logged at error level with a full stack trace.  The client only
 *       receives a 500 with a generic message so implementation details
 *       are never leaked.
 *
 * @param {Error}            err
 * @param {express.Request}  req
 * @param {express.Response} res
 * @param {express.NextFunction} next  - Required by Express even if unused.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Determine whether this is a known operational error ──────────────────
  const isOperational = err instanceof AppError && err.isOperational;

  // ── Logging ──────────────────────────────────────────────────────────────
  if (isOperational) {
    // Expected error: concise warn log is enough.
    console.warn(
      `[${err.code}] ${req.method} ${req.path} → ${err.statusCode}: ${err.message}`,
    );

    // For DatabaseError also log the underlying cause server-side only.
    if (err instanceof DatabaseError && err.original) {
      console.warn('  Underlying cause:', err.original.message);
    }
  } else {
    // Unexpected error: log the full stack for post-mortem debugging.
    console.error(
      `[UNEXPECTED_ERROR] ${req.method} ${req.path}\n`,
      err.stack ?? err,
    );
  }

  // ── Build the response body ───────────────────────────────────────────────
  const statusCode = isOperational ? err.statusCode : 500;

  const body = {
    error: {
      // Machine-readable code for programmatic handling by API consumers.
      code: isOperational ? err.code : 'INTERNAL_ERROR',

      // Human-readable message: real message for operational errors,
      // generic fallback for unexpected ones.
      message: isOperational
        ? err.message
        : 'An unexpected error occurred. Please try again later.',

      // Include per-field validation detail when present.
      ...(isOperational && err instanceof ValidationError && err.errors?.length > 0
        ? { errors: err.errors }
        : {}),
    },
  };

  // Avoid "Cannot set headers after they are sent" if a previous middleware
  // already started writing the response.
  if (res.headersSent) {
    return;
  }

  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Server bootstrap (skipped when file is required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

