'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── 1. AppError base ─────────────────────────────────────────────────────────
const base = new AppError('base', 500, 'BASE', false);
console.assert(base instanceof Error,    'AppError instanceof Error');
console.assert(base instanceof AppError, 'AppError instanceof AppError');
console.assert(base.statusCode  === 500,   'AppError.statusCode');
console.assert(base.code        === 'BASE', 'AppError.code');
console.assert(base.isOperational === false,'AppError.isOperational');
console.assert(base.name        === 'AppError', 'AppError.name');
console.log('AppError base ✓');

// ── 2. NotFoundError ─────────────────────────────────────────────────────────
const nfe = new NotFoundError('User 99 not found');
console.assert(nfe instanceof Error,        'NotFoundError instanceof Error');
console.assert(nfe instanceof AppError,     'NotFoundError instanceof AppError');
console.assert(nfe instanceof NotFoundError,'NotFoundError instanceof NotFoundError');
console.assert(nfe.statusCode  === 404,          'NotFoundError.statusCode');
console.assert(nfe.code        === 'NOT_FOUND',   'NotFoundError.code');
console.assert(nfe.isOperational === true,        'NotFoundError.isOperational');
console.assert(nfe.message     === 'User 99 not found', 'NotFoundError.message');
console.assert(nfe.name        === 'NotFoundError',     'NotFoundError.name');
console.log('NotFoundError ✓');

// Default message
const nfeDef = new NotFoundError();
console.assert(nfeDef.message === 'Resource not found', 'NotFoundError default message');
console.log('NotFoundError default message ✓');

// ── 3. ValidationError ───────────────────────────────────────────────────────
const ve = new ValidationError('Bad input', [{ field: 'email', message: 'required' }]);
console.assert(ve instanceof Error,           'ValidationError instanceof Error');
console.assert(ve instanceof AppError,        'ValidationError instanceof AppError');
console.assert(ve instanceof ValidationError, 'ValidationError instanceof ValidationError');
console.assert(ve.statusCode  === 422,               'ValidationError.statusCode');
console.assert(ve.code        === 'VALIDATION_ERROR', 'ValidationError.code');
console.assert(ve.isOperational === true,             'ValidationError.isOperational');
console.assert(ve.errors[0].field === 'email',        'ValidationError.errors[0].field');
console.assert(ve.name        === 'ValidationError',  'ValidationError.name');
console.log('ValidationError ✓');

// Default message + empty errors
const veDef = new ValidationError();
console.assert(veDef.message === 'Validation failed', 'ValidationError default message');
console.assert(Array.isArray(veDef.errors) && veDef.errors.length === 0, 'ValidationError default errors');
console.log('ValidationError defaults ✓');

// ── 4. DatabaseError ─────────────────────────────────────────────────────────
const cause = new Error('ETIMEDOUT');
const dbe = new DatabaseError('Query failed', cause);
console.assert(dbe instanceof Error,         'DatabaseError instanceof Error');
console.assert(dbe instanceof AppError,      'DatabaseError instanceof AppError');
console.assert(dbe instanceof DatabaseError, 'DatabaseError instanceof DatabaseError');
console.assert(dbe.statusCode  === 503,            'DatabaseError.statusCode');
console.assert(dbe.code        === 'DATABASE_ERROR','DatabaseError.code');
console.assert(dbe.isOperational === true,          'DatabaseError.isOperational');
console.assert(dbe.original    === cause,           'DatabaseError.original');
console.assert(dbe.name        === 'DatabaseError', 'DatabaseError.name');
console.log('DatabaseError ✓');

// Default message
const dbeDef = new DatabaseError();
