/**
 * errors.js
 *
 * Centralised application error hierarchy.
 *
 * Every class extends the base AppError so that the error-handling
 * middleware can distinguish "known, intentional" errors (safe to
 * surface to the client) from unexpected ones (which should be
 * swallowed and returned as a generic 500).
 *
 * Usage
 * -----
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   // In a route handler / service layer:
 *   throw new NotFoundError('User', 42);
 *   throw new ValidationError('email', 'must be a valid e-mail address');
 *   throw new DatabaseError('Failed to connect to replica');
 */

'use strict';

// ─── Base class ──────────────────────────────────────────────────────────────

/**
 * AppError
 *
 * The root of every intentional, operational error in this application.
 *
 * @property {number}  statusCode  - HTTP status code to send to the client.
 * @property {string}  code        - Machine-readable error code (e.g. "NOT_FOUND").
 * @property {boolean} isOperational
 *   true  → the error is expected / intentional; expose its message to clients.
 *   false → the error is a programmer mistake; swallow details, return 500.
 */
class AppError extends Error {
  /**
   * @param {string} message       - Human-readable description.
   * @param {number} statusCode    - HTTP status code.
   * @param {string} code          - Short, screaming-snake-case identifier.
   * @param {boolean} isOperational
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain the real class name in stack traces (important for subclasses).
    this.name = this.constructor.name;

    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── Concrete error classes ───────────────────────────────────────────────────

/**
 * NotFoundError  →  404
 *
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User', 42);
 *   // message → 'User with id 42 not found.'
 *
 * @example
 *   throw new NotFoundError('User');
 *   // message → 'User not found.'
 *
 * @example
 *   throw new NotFoundError();
 *   // message → 'Resource not found.'
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [resource]  - Name of the resource that was not found.
   * @param {string|number} [id] - Identifier that was looked up.
   */
  constructor(resource, id) {
    let message;

    if (resource && id !== undefined) {
      message = `${resource} with id ${id} not found.`;
    } else if (resource) {
      message = `${resource} not found.`;
    } else {
      message = 'Resource not found.';
    }

    super(message, 404, 'NOT_FOUND');
    this.resource = resource ?? null;
    this.resourceId = id ?? null;
  }
}

/**
 * ValidationError  →  422
 *
 * Thrown when client-supplied input fails validation before it reaches
 * the database or business logic.
 *
 * Accepts either a single field+message pair, or an array of field
 * violations for richer form-validation responses.
 *
 * @example  Single field
 *   throw new ValidationError('email', 'must be a valid e-mail address');
 *   // body → { code: 'VALIDATION_ERROR', message: '...', fields: { email: 'must be a valid e-mail address' } }
 *
 * @example  Multiple fields at once
 *   throw new ValidationError([
 *     { field: 'email',    message: 'is required' },
 *     { field: 'password', message: 'must be at least 8 characters' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string | Array<{field: string, message: string}>} fieldOrViolations
   *   Either a single field name, or an array of { field, message } objects.
   * @param {string} [message]
   *   When `fieldOrViolations` is a string, this is the per-field error message.
   */
  constructor(fieldOrViolations, message) {
    // ── Multi-field variant ───────────────────────────────────────────────
    if (Array.isArray(fieldOrViolations)) {
      const violations = fieldOrViolations;
      const summary = violations.map((v) => `${v.field}: ${v.message}`).join('; ');

      super(`Validation failed — ${summary}`, 422, 'VALIDATION_ERROR');

      // Build a convenient { field → message } lookup for the response body.
      this.fields = Object.fromEntries(violations.map((v) => [v.field, v.message]));
      return;
    }

    // ── Single-field variant ──────────────────────────────────────────────
    const field = fieldOrViolations;
    const fieldMessage = message ?? 'is invalid';

    super(`Validation failed — ${field}: ${fieldMessage}`, 422, 'VALIDATION_ERROR');

    this.fields = { [field]: fieldMessage };
  }
}

/**
 * DatabaseError  →  503
 *
 * Thrown when an interaction with the database fails in a way that is
 * recoverable (connection hiccup, timeout, constraint violation that
 * the application is aware of, etc.).
 *
 * For truly unexpected DB crashes, let the generic 500 handler take over
 * by NOT wrapping those in a DatabaseError — the missing `isOperational`
 * flag will cause the middleware to hide internals from the client.
 *
 * @example
 *   throw new DatabaseError('Connection to primary timed out');
 *   throw new DatabaseError('Unique constraint violation on users.email', originalErr);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]    - Description of what went wrong.
   * @param {Error}  [cause]      - Original error from the DB driver (not sent to client).
   */
  constructor(message = 'A database error occurred.', cause) {
    super(message, 503, 'DATABASE_ERROR');

    // Store the original driver error for internal logging without leaking it.
    this.cause = cause ?? null;
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application with centralised error-handling.
 *
 * Error flow
 * ──────────
 *  Route throws (or calls next(err) with) any Error subclass
 *        │
 *        ▼
 *  errorHandler middleware (registered last)
 *        │
 *        ├─ AppError (isOperational = true)  → expose message + code to client
 *        └─ Unknown / programmer error       → generic 500, log internally
 */

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();
app.use(express.json());

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Wrap an async route handler so that any rejected promise (or thrown
 * error) is automatically forwarded to Express's next(err) pipeline
 * instead of leaving a dangling, unhandled-rejection.
 *
 * @param {Function} fn  - async (req, res, next) => …
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Lightweight liveness probe — no database involvement.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Simulates a database call.  In production this would be something like:
 *   const users = await db.query('SELECT …');
 */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Simulate a DB layer that may throw.
    const users = await fetchAllUsers();
    res.json(users);
  }),
);

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Demonstrates:
 *  • ValidationError when the id is not a positive integer.
 *  • NotFoundError   when no user matches the id.
 */
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError('id', 'must be a positive integer');
    }

    const user = await fetchUserById(id);

    if (!user) {
      throw new NotFoundError('User', id);
    }

    res.json(user);
  }),
);

// ─── Catch-all 404 (must be placed after all real routes) ────────────────────

/**
 * Any request that didn't match a route above lands here.
 * We throw a NotFoundError so it passes through the same error handler
 * as every other error — no special-casing required.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl}`));
});

// ─── Centralised error-handling middleware ───────────────────────────────────

/**
 * errorHandler
 *
 * Must be the LAST piece of middleware registered (four-argument signature
 * is how Express recognises an error handler).
 *
 * Behaviour
 * ─────────
 * • Operational AppErrors  → HTTP status from the error, machine-readable body.
 * • Unexpected errors      → 500, generic message, full details kept server-side.
 *
 * Response shape
 * ──────────────
 * {
 *   "error": {
 *     "code":    "NOT_FOUND",          // from AppError.code
 *     "message": "User with id 9 not found.",
 *     "fields":  { … }                 // only present on ValidationError
 *   }
 * }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Operational (known) errors ────────────────────────────────────────────
  if (err instanceof AppError && err.isOperational) {
    const body = {
      error: {
        code: err.code,
        message: err.message,
      },
    };

    // Attach per-field detail only when the error carries it.
    if (err instanceof ValidationError && err.fields) {
      body.error.fields = err.fields;
    }

    // Surface the original DB cause in non-production environments to help
    // with debugging, but never expose raw driver errors to production clients.
    if (err instanceof DatabaseError && err.cause && process.env.NODE_ENV !== 'production') {
      body.error.cause = err.cause.message;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Unexpected / programmer errors ───────────────────────────────────────
  // Log the full error internally …
  console.error('[Unhandled error]', err);

  // … but tell the client as little as possible.
  return res.status(500).json({
    error: {
      code: 'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ─── Simulated data-access layer ─────────────────────────────────────────────
// Replace these stubs with real DB calls (pg, mongoose, prisma, …).
// They throw DatabaseError on failure so that routes stay free of
// driver-specific error handling.

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

async function fetchAllUsers() {
  try {
    // await db.query(…)
    return USERS;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve users.', err);
  }
}

async function fetchUserById(id) {
  try {
    // await db.query('SELECT … WHERE id = $1', [id])
