console.assert(ve1.code           === 'VALIDATION_ERROR',               'VE code');
console.assert(ve1.fields.email   === 'must be valid',                  'VE single field.email');
console.assert(ve1.message.includes('email'),                           'VE message includes field');

// ── ValidationError (multi-field) ────────────────────────────────────────────
const ve2 = new ValidationError([
  { field: 'email',    message: 'is required' },
  { field: 'password', message: 'must be ≥ 8 chars' },
]);
console.assert(ve2.fields.email    === 'is required',   'VE multi fields.email');
console.assert(ve2.fields.password === 'must be ≥ 8 chars', 'VE multi fields.password');
console.log('ValidationError     ✓');

// ── DatabaseError ────────────────────────────────────────────────────────────
