const de = new DatabaseError('Connection failed', cause);
console.assert(de.statusCode === 503,                'DBE statusCode');
console.assert(de.code       === 'DATABASE_ERROR',   'DBE code');
console.assert(de.cause      === cause,              'DBE cause stored');

const deNoArgs = new DatabaseError();
console.assert(deNoArgs.message === 'A database error occurred.', 'DBE default message');
console.assert(deNoArgs.cause   === null,                         'DBE no-cause null');
console.log('DatabaseError       ✓');

// ── All are AppError subclasses ──────────────────────────────────────────────
console.assert(nf1 instanceof AppError, 'NotFoundError  instanceof AppError');
console.assert(ve1 instanceof AppError, 'ValidationError instanceof AppError');
