/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and adds:
 *   - statusCode  – the HTTP status that should be returned to the client
 *   - code        – a stable machine-readable string useful for clients / logging
 *   - isOperational – true for errors that are "expected" (bad input, missing
 *                     resource, …); false-y value means the process should be
 *                     treated as an unhandled programmer mistake.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message        Human-readable description.
   * @param {number} statusCode     HTTP status code (default 500).
   * @param {string} code           Machine-readable error code.
   * @param {boolean} isOperational Whether this is an expected operational
   *                                error (true) or a programmer bug (false).
   */
  constructor(
    message,
    statusCode = 500,
    code = 'INTERNAL_ERROR',
    isOperational = true,
  ) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation and in plain Node.js alike.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = new.target.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Returns a plain object safe to serialise into a JSON response body.
   * Sensitive internals (stack trace) are intentionally excluded.
   */
  toJSON() {
    return {
      error: {
        code: this.code,
        message: this.message,
        statusCode: this.statusCode,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] Optional label for the missing resource,
   *                            e.g. "User" or "Order #42".
   */
  constructor(resource = 'Resource') {
    super(`${resource} not found.`, 404, 'NOT_FOUND');
  }
}

// ---------------------------------------------------------------------------
// 422 – semantic / business-rule validation failure
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}   message Human-readable summary of what failed.
   * @param {Object[]} [fields] Optional per-field detail array, each item
   *                            shaped as { field: string, message: string }.
   *                            Useful for form-validation responses.
   */
  constructor(message = 'Validation failed.', fields = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.fields = fields;
  }

  toJSON() {
    const base = super.toJSON();
    if (this.fields.length > 0) {
      base.error.fields = this.fields;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 – database / persistence layer error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]        Public-safe description.
   * @param {Error}  [originalError]  The raw driver / ORM error for internal
   *                                  logging — never forwarded to clients.
   */
  constructor(
    message = 'A database error occurred. Please try again later.',
    originalError = null,
  ) {
    // isOperational = false: a DB failure is unexpected and may warrant
    // alerting / process restart in production.
    super(message, 503, 'DATABASE_ERROR', false);

    // Stash the original low-level error for server-side logging only.
    // It is deliberately NOT included in toJSON() so connection strings,
    // table names, etc. never leak to the client.
    if (originalError) {
      this.originalError = originalError;
    }
  }
