// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 * Express application with centralised error-handling middleware.
 *
 * Error flow
 * ──────────
 *  Route / middleware detects a problem
 *    └─► throws an AppError subclass  (or calls next(err) for async routes)
 *          └─► errorHandler middleware formats & sends the JSON response
 *                └─► unhandledRejection / uncaughtException safety-net logs
 *                    non-operational errors and exits so a process manager
 *                    (PM2, Kubernetes, …) can restart cleanly.
 */

'use strict';

const express = require('express');
const {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
} = require('./errors');

const app = express();

app.use(express.json());

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Wraps an async route handler so that any rejected promise is forwarded to
 * Express's next(err) automatically — no try/catch boilerplate in every route.
 *
 * @param {Function} fn  Async (req, res, next) handler.
 * @returns {Function}   Standard Express middleware.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ─── Routes ─────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe — always operational, never throws.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns a static list of users.
 *
 * Demonstrates: throwing a DatabaseError when the persistence layer fails.
 */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Simulated data layer — replace with a real DB call.
    const rows = await fetchUsers();
    res.json(rows);
  }),
);

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Demonstrates:
 *   - throwing a ValidationError for a non-numeric id parameter
 *   - throwing a NotFoundError when no record matches
 */
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError('User id must be a positive integer.', [
        { field: 'id', message: 'Must be a positive integer.' },
      ]);
    }

    const user = await fetchUserById(id);

    if (!user) {
      throw new NotFoundError(`User #${id}`);
    }

    res.json(user);
  }),
);

/**
 * POST /users
 * Creates a new user.
 *
 * Demonstrates: throwing a ValidationError for missing or malformed fields.
 */
app.post(
  '/users',
  asyncHandler(async (req, res) => {
    const { name, email } = req.body ?? {};
    const fieldErrors = [];

    if (!name || typeof name !== 'string' || name.trim() === '') {
      fieldErrors.push({ field: 'name', message: 'Name is required.' });
    }

    if (!email || typeof email !== 'string' || !email.includes('@')) {
      fieldErrors.push({
        field: 'email',
        message: 'A valid email address is required.',
      });
    }

    if (fieldErrors.length > 0) {
      throw new ValidationError('Invalid user data.', fieldErrors);
    }

    const newUser = await createUser({ name: name.trim(), email });
    res.status(201).json(newUser);
  }),
);

// ─── 404 catch-all ──────────────────────────────────────────────────────────
// Must be registered AFTER all real routes.

app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl}`));
});

// ─── Centralised error-handling middleware ───────────────────────────────────
// Four-argument signature is required by Express to treat this as an error
// handler rather than a regular middleware.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Normalise to AppError ──────────────────────────────────────────────
  // If something outside our code threw a plain Error (e.g. JSON.parse,
  // a third-party library) we wrap it so the rest of the handler is uniform.
  const appError =
    err instanceof AppError
      ? err
      : new AppError(
          'An unexpected error occurred.',
          500,
          'INTERNAL_ERROR',
          false, // non-operational → log loudly
        );

  // ── 2. Logging ───────────────────────────────────────────────────────────
  // Operational errors (bad input, missing resource) are low-severity.
  // Non-operational errors (DB down, programmer mistake) warrant full stack.
  if (appError.isOperational) {
    console.warn('[operational error]', {
      code: appError.code,
      statusCode: appError.statusCode,
      message: appError.message,
      // For DatabaseError the originalError exists but we only log it
      // server-side; it is never sent to the client (see toJSON).
      ...(appError.originalError && {
        originalMessage: appError.originalError.message,
      }),
    });
  } else {
    console.error('[non-operational error]', {
      code: appError.code,
      statusCode: appError.statusCode,
      message: appError.message,
      stack: appError.stack,
      // Preserve the original driver error for diagnostics if present.
      ...(appError.originalError && {
        originalError: appError.originalError,
      }),
    });
  }

  // ── 3. Response ───────────────────────────────────────────────────────────
  // toJSON() on every AppError subclass is guaranteed to exclude internal
  // details (stack, originalError, driver messages, etc.).
  res.status(appError.statusCode).json(appError.toJSON());
});

// ─── Simulated data-layer functions ─────────────────────────────────────────
// Replace these stubs with real database calls; the error-handling contract
// (throw DatabaseError on failure) stays the same.

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

async function fetchUsers() {
  try {
    // Simulate async I/O (e.g. a DB query).
    return await Promise.resolve(USERS);
  } catch (err) {
    throw new DatabaseError('Unable to retrieve users.', err);
  }
}

async function fetchUserById(id) {
  try {
    const user = USERS.find((u) => u.id === id) ?? null;
    return await Promise.resolve(user);
  } catch (err) {
    throw new DatabaseError(`Unable to retrieve user #${id}.`, err);
  }
}

async function createUser(data) {
  try {
    const newUser = { id: USERS.length + 1, ...data };
    USERS.push(newUser);
    return await Promise.resolve(newUser);
  } catch (err) {
    throw new DatabaseError('Unable to create user.', err);
  }
}

// ─── Server bootstrap ────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// ─── Process-level safety net ────────────────────────────────────────────────
// Non-operational errors (uncaught exceptions, unhandled rejections) are
// logged here and the process exits so a supervisor can restart cleanly.

process.on('unhandledRejection', (reason) => {
  console.error('[unhandledRejection]', reason);
  // Give the server a moment to finish in-flight requests before exiting.
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (err) => {
  console.error('[uncaughtException]', err);
  server.close(() => process.exit(1));
});

module.exports = app;

