'use strict';
// ── Inline minimal express mock ──────────────────────────────────────────────
// We only need: app.use(), app.get(), app.post(), app.listen() stubs,
// and the ability to simulate requests through the middleware chain.
function makeMockApp() {
  const layers = [];

  function use(...args) {
    const path   = typeof args[0] === 'string' ? args[0] : null;
    const fns    = args.filter(a => typeof a === 'function');
    layers.push({ method: null, path, fns });
  }
  function addRoute(method, path, ...fns) {
    layers.push({ method, path, fns });
  }

  function matchPath(layerPath, reqPath) {
    if (!layerPath) return { match: true, params: {} };
    // Simple :param support
    const lp = layerPath.replace(/:([^/]+)/g, '([^/]+)');
    const names = [];
    layerPath.replace(/:([^/]+)/g, (_, n) => names.push(n));
    const re = new RegExp('^' + lp + '\$');
    const m  = reqPath.match(re);
    if (!m) return { match: false };
    const params = {};
    names.forEach((n, i) => { params[n] = m[i + 1]; });
    return { match: true, params };
  }

  async function handle(method, path, body) {
    let idx = 0;
    const req = { method, path, originalUrl: path, params: {}, body };
    let statusCode = 200;
    let responseBody;

    const res = {
      statusCode,
      status(code) { this.statusCode = code; return this; },
      json(obj)    { responseBody = obj; },
    };

    const eligible = layers.filter(l =>
      (l.method === null || l.method === method) &&
      matchPath(l.path, path).match
    );

    async function next(err) {
      const layer = eligible[idx++];
      if (!layer) return;
      const { params } = matchPath(layer.path, path);
      req.params = { ...req.params, ...params };

      if (err) {
        // Find next error handler (4-arg)
        for (let i = idx - 1; i < eligible.length; i++) {
          for (const fn of eligible[i].fns) {
            if (fn.length === 4) {
              idx = i + 1;
              await fn(err, req, res, next);
              return;
            }
          }
        }
        return;
      }

      for (const fn of layer.fns) {
        if (fn.length < 4) {
          await Promise.resolve(fn(req, res, next)).catch(next);
          return;
        }
      }
    }
    await next();
    return { status: res.statusCode, body: responseBody };
  }

  return {
    use,
    get:    (path, ...fns) => addRoute('GET',  path, ...fns),
    post:   (path, ...fns) => addRoute('POST', path, ...fns),
    listen: () => {},
    _handle: handle,
    _layers: layers,
  };
}

