/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and carries:
 *   - message  – human-readable description (inherited from Error)
 *   - status   – HTTP status code sent to the client
 *   - code     – machine-readable identifier for the error type
 *   - details  – optional extra context (validation fields, DB table, etc.)
 *
 * Usage inside a route handler:
 *
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Invalid payload', [{ field: 'email', msg: 'required' }]);
 *   throw new DatabaseError('Query failed', { table: 'users' });
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message          - Human-readable error description.
   * @param {number}  status           - HTTP status code (default 500).
   * @param {string}  code             - Machine-readable error code.
   * @param {*}       [details]        - Optional structured details.
   */
  constructor(message, status = 500, code = 'INTERNAL_ERROR', details = null) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation (also good practice in plain Node.js).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name    = this.constructor.name;
    this.status  = status;
    this.code    = code;
    this.details = details;

    // Capture a clean stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Returns a plain object safe to serialise as a JSON response body.
   * Sensitive internal details (e.g. raw DB errors) are excluded in
   * production; they are only included when NODE_ENV !== 'production'.
   */
  toJSON() {
    const payload = {
      error: {
        code:    this.code,
        message: this.message,
      },
    };

    if (this.details !== null && this.details !== undefined) {
      payload.error.details = this.details;
    }

    // Include the stack trace only outside of production to avoid leaking
    // internal implementation details to API consumers.
    if (process.env.NODE_ENV !== 'production' && this.stack) {
      payload.error.stack = this.stack;
    }

    return payload;
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * Thrown when a requested resource does not exist.
   *
   * @param {string} [message]   - Defaults to 'Resource not found'.
   * @param {*}      [details]   - Optional extra context (e.g. { id: 42 }).
   *
   * @example
   *   throw new NotFoundError('User not found', { id: req.params.id });
   */
  constructor(message = 'Resource not found', details = null) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

// ---------------------------------------------------------------------------
// 422 Unprocessable Entity – Validation
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * Thrown when request input fails validation rules.
   *
   * @param {string}                message  - Summary of what went wrong.
   * @param {Array<{field: string,
   *                msg:   string}>} [fields] - Per-field validation failures.
   *
   * @example
   *   throw new ValidationError('Invalid user payload', [
   *     { field: 'email',    msg: 'Must be a valid email address' },
   *     { field: 'password', msg: 'Must be at least 8 characters' },
   *   ]);
   */
  constructor(message = 'Validation failed', fields = []) {
    super(message, 422, 'VALIDATION_ERROR', { fields });
  }
}

// ---------------------------------------------------------------------------
// 503 Service Unavailable – Database
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * Thrown when a database operation fails.
   * Wraps the original error so it can be inspected during debugging while
   * keeping raw driver errors out of the API response in production.
   *
   * @param {string} [message]       - Human-readable description.
   * @param {Error|*} [originalError] - The underlying driver/ORM error.
   *
   * @example
   *   try {
   *     await db.query('SELECT ...');
   *   } catch (err) {
   *     throw new DatabaseError('Failed to fetch users', err);
   *   }
   */
  constructor(message = 'A database error occurred', originalError = null) {
    // Expose the original error message in non-production environments only.
    const details =
      originalError && process.env.NODE_ENV !== 'production'
        ? {
            originalMessage: originalError.message ?? String(originalError),
          }
        : null;

    super(message, 503, 'DATABASE_ERROR', details);

    // Keep a reference for internal logging without leaking it to toJSON().
    this.originalError = originalError;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 * Express application with centralised error handling middleware.
 *
 * Error flow
 * ----------
 * Route handlers throw AppError subclasses (NotFoundError, ValidationError,
 * DatabaseError).  Async handlers are wrapped with asyncHandler() so that
 * rejected promises are forwarded to Express's next(err) automatically,
 * without repetitive try/catch blocks in every route.
 *
 * The two error-handling middleware functions at the bottom of the file are
 * the single source of truth for how errors are formatted and logged:
 *
 *   1. notFoundHandler  – catches requests that matched no route (404).
 *   2. errorHandler     – formats every AppError (and unexpected errors) into
 *                         a consistent JSON response.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Utility – async route wrapper
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so any rejected promise is forwarded to
 * Express's error-handling pipeline via next(err).
 *
 * Without this wrapper every async handler would need its own try/catch.
 *
 * @param   {Function} fn  - Async (req, res, next) handler.
 * @returns {Function}     - Express-compatible middleware.
 *
 * @example
 *   app.get('/users/:id', asyncHandler(async (req, res) => {
 *     const user = await db.find(req.params.id); // may throw NotFoundError
 *     res.json(user);
 *   }));
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// In-memory data store (replaces a real DB for this example)
// ---------------------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// Minimal email regex used by the validation helper below.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// ---------------------------------------------------------------------------
// Validation helper
// ---------------------------------------------------------------------------

/**
 * Validates a new-user request body.
 * Throws a ValidationError that lists every field-level failure at once
 * (rather than stopping at the first problem) so clients can fix everything
 * in a single round-trip.
 *
 * @param {object} body - Parsed JSON request body.
 * @throws {ValidationError}
 */
function validateUserBody(body) {
  const fields = [];

  if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
    fields.push({ field: 'name', msg: 'name is required and must be a non-empty string' });
  }

  if (!body.email || typeof body.email !== 'string') {
    fields.push({ field: 'email', msg: 'email is required and must be a string' });
  } else if (!EMAIL_RE.test(body.email.trim())) {
    fields.push({ field: 'email', msg: 'email must be a valid email address' });
  }

  if (fields.length > 0) {
    throw new ValidationError('Invalid user payload', fields);
  }
}

