 * Demonstrates ValidationError: thrown when the supplied ID is not a number.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new ValidationError('Invalid user ID', [
      { field: 'id', msg: 'id must be a positive integer' },
    ]);
  }

  let user;

  try {
    user = await Promise.resolve(USERS.find((u) => u.id === id));
  } catch (err) {
    throw new DatabaseError('Failed to retrieve user', err);
  }

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, { id });
  }

  res.json(user);
}));

// -- POST /users ------------------------------------------------------------

/**
 * Creates a new user.
 *
 * Demonstrates ValidationError: validateUserBody() inspects the body and
 * throws with full field-level detail when anything is missing or malformed.
 * Demonstrates DatabaseError: wraps the persistence call.
 */
app.post('/users', asyncHandler(async (req, res) => {
  // Throws ValidationError if the body does not pass validation.
  validateUserBody(req.body);

  const { name, email } = req.body;

  let newUser;

  try {
    newUser = await Promise.resolve({
      id:    USERS.length + 1,
      name:  name.trim(),
      email: email.trim(),
    });

    USERS.push(newUser);
  } catch (err) {
    throw new DatabaseError('Failed to create user', err);
  }

  res.status(201).json(newUser);
}));

// -- DELETE /users/:id -------------------------------------------------------

/**
 * Deletes a user by numeric ID.
 *
 * Demonstrates NotFoundError: thrown when the ID does not match any record.
 * Demonstrates ValidationError: thrown for a non-numeric ID segment.
 * Demonstrates DatabaseError: wraps the persistence call.
 */
app.delete('/users/:id', asyncHandler(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new ValidationError('Invalid user ID', [
      { field: 'id', msg: 'id must be a positive integer' },
    ]);
  }

  const index = USERS.findIndex((u) => u.id === id);

  if (index === -1) {
    throw new NotFoundError(`User with id ${id} not found`, { id });
  }

  try {
    await Promise.resolve(USERS.splice(index, 1));
  } catch (err) {
    throw new DatabaseError('Failed to delete user', err);
  }

  res.status(204).send();
