    if (this.details !== null && this.details !== undefined) {
      payload.error.details = this.details;
    }

    return payload;
  }
}

// ─── Concrete error classes ───────────────────────────────────────────────────

/**
 * NotFoundError  (HTTP 404)
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', { id: 42 });
 */
class NotFoundError extends AppError {
  /**
   * @param {string} message          - Defaults to 'Resource not found'.
   * @param {*}      [details]        - Optional context (e.g. { id, type }).
   */
  constructor(message = 'Resource not found', details = null) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

/**
 * ValidationError  (HTTP 422)
 * Thrown when incoming data fails business-rule or schema validation.
 *
 * The `details` field is conventionally an array of per-field error objects
 * so that clients can display contextual feedback:
 *
 * @example
 *   throw new ValidationError('Invalid request body', [
 *     { field: 'email', issue: 'Must be a valid email address' },
 *     { field: 'age',   issue: 'Must be a positive integer'    },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string} message          - Defaults to 'Validation failed'.
   * @param {*}      [details]        - Structured field errors.
   */
  constructor(message = 'Validation failed', details = null) {
    super(message, 422, 'VALIDATION_ERROR', details);
  }
}

/**
 * DatabaseError  (HTTP 503)
 * Thrown when an interaction with the database fails (query error, connection
 * timeout, constraint violation, etc.).
 *
 * @example
 *   throw new DatabaseError('Failed to fetch users', { operation: 'SELECT' });
 */
class DatabaseError extends AppError {
  /**
   * @param {string} message          - Defaults to 'Database operation failed'.
   * @param {*}      [details]        - Optional context (operation, table …).
   */
  constructor(message = 'Database operation failed', details = null) {
    super(message, 503, 'DATABASE_ERROR', details);
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 * Express application with centralised error-handling middleware.
 *
 * Error flow
 * ──────────
 *  Route/middleware throws  →  next(err) (async wrapper) or throw (sync)
 *       ↓
 *  errorHandler middleware  →  maps AppError subclasses to JSON responses
 *       ↓
 *  Client receives a consistent { error: { code, message, [details] } } shape
 */

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();
app.use(express.json());

// ─── Utility ─────────────────────────────────────────────────────────────────

/**
 * asyncHandler
 * Wraps an async route handler so that any rejected promise (or thrown error)
 * is forwarded to Express's next(err) pipeline automatically.
 * This removes the need for try/catch boilerplate in every route.
 *
 * @param   {Function} fn  - Async route handler (req, res, next) => Promise
 * @returns {Function}     - Standard Express middleware
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Liveness probe – always returns 200 when the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Demonstrates: DatabaseError on a simulated data-layer failure.
 */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Simulated data layer -------------------------------------------------
    // Replace this block with your real DB call.  If the call rejects, throw
    // a DatabaseError so the error handler returns a consistent 503 response.
    const fetchUsers = async () => [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    let users;
    try {
      users = await fetchUsers();
    } catch (dbErr) {
      throw new DatabaseError('Failed to retrieve users', { operation: 'SELECT users' });
    }
    // -----------------------------------------------------------------------

    res.json(users);
  }),
);

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Demonstrates:
 *  - ValidationError when the `:id` param is not a positive integer.
 *  - NotFoundError  when no user matches the supplied ID.
 */
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const rawId = req.params.id;

    // ── Validate ────────────────────────────────────────────────────────────
    const id = Number(rawId);
    if (!Number.isInteger(id) || id < 1) {
      throw new ValidationError('Invalid user ID', [
        { field: 'id', issue: 'Must be a positive integer' },
      ]);
    }

    // ── Simulated data layer ────────────────────────────────────────────────
    const fetchUserById = async (userId) => {
      const store = {
        1: { id: 1, name: 'Alice', email: 'alice@example.com' },
        2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
      };
      return store[userId] ?? null;
    };

    let user;
    try {
      user = await fetchUserById(id);
    } catch (dbErr) {
      throw new DatabaseError('Failed to retrieve user', { operation: 'SELECT user', id });
    }

    if (!user) {
      throw new NotFoundError(`User with ID ${id} not found`, { id });
    }
    // ────────────────────────────────────────────────────────────────────────

    res.json(user);
  }),
);

/**
 * POST /users
 * Creates a new user.
 *
 * Demonstrates: ValidationError with multiple field-level messages.
 */
app.post(
  '/users',
  asyncHandler(async (req, res) => {
    const { name, email } = req.body ?? {};

    // ── Validate ────────────────────────────────────────────────────────────
    const fieldErrors = [];

    if (!name || typeof name !== 'string' || name.trim() === '') {
      fieldErrors.push({ field: 'name', issue: 'Name is required and must be a non-empty string' });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || typeof email !== 'string' || !emailRegex.test(email)) {
      fieldErrors.push({ field: 'email', issue: 'A valid email address is required' });
    }

    if (fieldErrors.length > 0) {
      throw new ValidationError('Invalid request body', fieldErrors);
    }
    // ────────────────────────────────────────────────────────────────────────

    // ── Simulated data layer ────────────────────────────────────────────────
    const createUser = async (data) => ({ id: Date.now(), ...data });

    let newUser;
    try {
      newUser = await createUser({ name: name.trim(), email });
    } catch (dbErr) {
      throw new DatabaseError('Failed to create user', { operation: 'INSERT user' });
    }
    // ────────────────────────────────────────────────────────────────────────

    res.status(201).json(newUser);
  }),
);

// ─── 404 catch-all ───────────────────────────────────────────────────────────
// Must be placed after all real routes so it only fires when nothing matched.

app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
});

// ─── Centralised error-handling middleware ────────────────────────────────────
// Express recognises a 4-argument middleware as an error handler.
// It MUST be registered after all routes and other middleware.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Operational errors (thrown deliberately by our code) ─────────────────
  if (err instanceof AppError) {
    return res.status(err.statusCode).json(err.toJSON());
  }

  // ── Unexpected / programmer errors ───────────────────────────────────────
  // Log the full stack so it appears in server logs but never send raw
  // error internals to the client.
  console.error('[Unhandled Error]', err);

  return res.status(500).json({
    error: {
      code:    'INTERNAL_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ─── Server ───────────────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;
